{
  "compilerOptions": {
    "target": "ES2023",
    "lib": ["ES2023"],
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "types": ["node"]
  },
  "include": ["check.ts"]
}
EOF
cat > check.ts <<'EOF'
import Database from 'better-sqlite3'
import express from 'express'
import pino from 'pino'
import { z } from 'zod'
import { createPublicClient, http, fallback, type PublicClient, type Hex } from 'viem'
import { sendRawTransaction } from 'viem/actions'
import { anvil } from 'viem/chains'
const db = new Database(':memory:'); db.pragma('journal_mode = WAL')
const row = db.prepare('select 1 as x').get() as { x: number }
const client: PublicClient = createPublicClient({ chain: anvil, transport: fallback([http('http://a'), http('http://b')]) })
const send = (raw: Hex) => sendRawTransaction(client, { serializedTransaction: raw })
const app = express(); app.use(express.json({ limit: '256kb' }))
app.get('/x', async (_req, res) => { res.status(200).json({ ok: row.x }) })
const log = pino({ redact: ['privateKey', '*.privateKey'] })
const S = z.strictObject({ chainId: z.number().int().positive(), data: z.string().default('0x') })
const parsed = S.safeParse({ chainId: 1 }); if (!parsed.success) log.info(parsed.error.issues)
export { send }
EOF
npx tsc -p tsconfig.json && echo TSC_OK && echo 'import Database from "better-sqlite3"; import pino from "pino"; console.log(typeof Database, typeof pino)' > run.ts && npx tsx run.ts

