/**
 * The free nonces of one (chain, sender): nonces given back by rollback, plus the top, the next
 * nonce never used. Adapted from the Rust pool described in ADR 0009.
 *
 * None of the methods awaits, so Node runs each one without interruption and no lock is needed.
 */
export class NoncePool {
  /** Ascending. The last entry is the top; any entry below it is a gap. */
  #free: number[]
  /** When each gap opened, so the gap filler can wait before taking it. */
  readonly #openedAt = new Map<number, number>()
  readonly #now: () => number

  constructor(top: number, gaps: number[] = [], now: () => number = Date.now) {
    this.#now = now
    this.#free = [top]
    for (const gap of gaps) this.rollback(gap)
  }

  /**
   * Rebuilds a sender's pool at startup (ADR 0009). `held` are the nonces of unfinished requests
   * that a node may have; every other nonce from `confirmed` up to the top is free.
   */
  static rebuild(
    { confirmed, pending, held }: { confirmed: number; pending: number; held: number[] },
    now: () => number = Date.now,
  ): NoncePool {
    const live = new Set(held.filter((nonce) => nonce >= confirmed))
    const top = Math.max(confirmed, pending, ...[...live].map((nonce) => nonce + 1))
    const gaps: number[] = []
    for (let nonce = confirmed; nonce < top; nonce++) if (!live.has(nonce)) gaps.push(nonce)
    return new NoncePool(top, gaps, now)
  }

  get top(): number {
    return this.#free[this.#free.length - 1]
  }

  get gaps(): number[] {
    return this.#free.slice(0, -1)
  }

  /** The smallest free nonce, so gaps are filled before new nonces are used. */
  take(): number {
    const nonce = this.#free.shift()!
    this.#openedAt.delete(nonce)
    if (this.#free.length === 0) this.#free.push(nonce + 1)
    return nonce
  }

  /** Only call this when no node can have a transaction with this nonce (ADR 0009). */
  rollback(nonce: number): void {
    if (nonce >= this.top || this.#free.includes(nonce)) return
    this.#free.push(nonce)
    this.#free.sort((a, b) => a - b)
    this.#openedAt.set(nonce, this.#now())
    this.#mergeIntoTop()
  }

  /** Drops every free nonce the chain has already used. */
  reset(confirmed: number): void {
    this.#free = this.#free.filter((nonce) => nonce >= confirmed)
    for (const nonce of this.#openedAt.keys()) if (nonce < confirmed) this.#openedAt.delete(nonce)
    if (this.#free.length === 0) this.#free.push(confirmed)
  }

  /** Whether the lowest gap has been open for at least `minAgeMs`. */
  hasGap(minAgeMs: number): boolean {
    if (this.#free.length < 2) return false
    return this.#now() - this.#openedAt.get(this.#free[0])! >= minAgeMs
  }

  /** Takes the lowest gap once it has been open for at least `minAgeMs`. Never returns the top. */
  takeGap(minAgeMs: number): number | undefined {
    return this.hasGap(minAgeMs) ? this.take() : undefined
  }

  // While the nonce below the top is free, it becomes the new top: {6, 7, 8} → {6}.
  #mergeIntoTop(): void {
    const free = this.#free
    while (free.length >= 2 && free[free.length - 2] === free[free.length - 1] - 1) {
      free.pop()
      this.#openedAt.delete(free[free.length - 1])
    }
  }
}

