    await rt.testClient.setAutomine(false) // keep them submitted
    const txs = Array.from({ length: 3 }, () => rt.submit())
    await rt.worker.idle()
    expect(txs.map((tx) => rt.store.get(tx.id)!.status)).toEqual(['submitted', 'submitted', 'queued'])

