    expect(outcomes(rt, tx.id)).toEqual(['unknown'])
    expect(rt.senders.get(anvil.id, ADDRESS_0).pool.top).toBe(1)
  })

  test('a clear rejection fails the request and gives its nonce to the next one', async () => {
    let sends = 0
