    await rt.worker.idle()
    expect(rt.store.get(rejected.id)).toMatchObject({
      status: 'failed',
      error: { code: 'BROADCAST_REJECTED', message: 'intrinsic gas too low' },
    })

    const next = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(next.id)).toMatchObject({ status: 'submitted', nonce: 0 })
  })

  test('"nonce too high" on an unused nonce is retried shortly, with the same nonce', async () => {
    let sends = 0
    const rt = await createRuntime(node.url, {
      wrapSenders: ([real]) => [
        async (raw) => {
          if (sends++ === 0) throw nodeError('nonce too high')
          return real(raw)
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0 })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'accepted'])
  })

  test('gives up after the "nonce too high" retry limit and frees the nonce', async () => {
    const rt = await createRuntime(node.url, {
      worker: { nonceTooHighRetries: 2 },
      wrapSenders: () => [
        async () => {
          throw nodeError('nonce too high')
        },
