    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'failed', error: { code: 'BROADCAST_REJECTED' } })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'rejected', 'rejected'])
    expect(rt.senders.get(anvil.id, ADDRESS_0).pool.top).toBe(0)
  })

  test('when another tx already used the nonce, resyncs from the chain and retries with a fresh one', async () => {
    const rt = await createRuntime(node.url)
    // Uses nonce 0 behind the pool's back.
    const outsider = createWalletClient({ account: privateKeyToAccount(KEY_0), chain: anvil, transport: http(node.url) })
    await outsider.sendTransaction({ to: ADDRESS_1, value: 1n })

    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 1 })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'accepted'])
  })

  test('when our own tx was mined despite an error, counts it as accepted and does not retry', async () => {
    // Like a load balancer that forwards the tx to one backend, then returns another backend's error.
    const rt = await createRuntime(node.url, {
