      try {
        const gasLimit = await estimateGasLimit(read, tx, gas.gasLimitBufferPercent)
        const fees = priceFees(await readMarketFees(read, gas.type), gas)
        if (fees === 'above_cap') {
          return { code: 'FEE_ABOVE_CAP', message: `base fee plus tip is above the cap of ${gas.maxFeePerGasWei} wei` }
        }
        return { gasLimit, fees }
      } catch (error) {
        const answer = describeSendError(error)
        if (answer.answered) {
          const funds = classifyNodeMessage(answer.message) === 'insufficient_funds'
          return { code: funds ? 'INSUFFICIENT_FUNDS' : 'ESTIMATION_REVERTED', message: answer.message }
        }
        if (!isTransportError(error)) throw error
        const remaining = deadline - Date.now()
        if (remaining <= 0) {
          const seconds = this.#options.preBroadcastWindowMs / 1000
          return { code: 'RPC_UNAVAILABLE', message: `the RPC was unreachable for ${seconds} s` }
        }
        await sleep(Math.min(this.#options.backoffBaseMs * 2 ** attempt, this.#options.maxBackoffMs, remaining))
      }
    }
  }

  /** Takes a nonce as late as possible, then signs, saves and broadcasts (ADR 0009). */
  async #submit(
    tx: TxRecord,
    prepared: Prepared,
    chain: RuntimeChain,
    account: LocalAccount,
    state: SenderState,
    log: Logger,
  ): Promise<JobResult> {
    const { store } = this.#deps
    let tooHighRetries = 0
    let tooLowRetries = 0

    for (;;) {
      const nonce = state.pool.take()
      let attempt: Attempt
      try {
        const signed = await signAttempt(account, { ...tx, nonce, ...prepared })
        attempt = store.recordAttempt(tx.id, { nonce, ...prepared, ...signed })
      } catch (error) {
        state.pool.rollback(nonce) // nothing was sent
        throw error
      }

      const result = await broadcast(attempt.raw, chain.rpc.senders, {
        maxSends: this.#options.broadcastSends,
        delayMs: this.#options.broadcastDelayMs,
      })
      if (result.outcome !== 'rejected') {
        return this.#submitted(tx, attempt, result.outcome, nonce, log)
      }

      store.setAttemptOutcome(attempt.id, 'rejected')
      log.info({ nonce, hash: attempt.hash, reason: result.reason, nodeMessage: result.message }, 'broadcast rejected')
      const verdict = await this.#explainRejection(tx.sender, nonce, attempt.hash, chain, result)
      switch (verdict.kind) {
        case 'ours_on_chain':
          log.warn({ nonce, hash: attempt.hash }, 'rejected, but our transaction is on chain')
          return this.#submitted(tx, attempt, 'accepted', nonce, log)
        case 'undecided':
          return this.#submitted(tx, attempt, 'unknown', nonce, log)
        case 'nonce_used':
          state.pool.reset(verdict.confirmed)
          log.warn({ nonce, confirmed: verdict.confirmed }, 'nonce already used on chain, pool resynced')
          if (++tooLowRetries > this.#options.nonceTooLowRetries) {
            return this.#fail(tx, { code: 'BROADCAST_REJECTED', message: result.message }, log)
          }
          continue
        case 'retry_later':
          state.pool.rollback(nonce)
          if (++tooHighRetries > this.#options.nonceTooHighRetries) {
            return this.#fail(tx, { code: 'BROADCAST_REJECTED', message: result.message }, log)
          }
          await sleep(this.#options.nonceRetryDelayMs)
          continue
        case 'failed':
          state.pool.rollback(nonce)
          return this.#fail(tx, verdict.failure, log)
      }
    }
  }

  /**
   * A clear rejection means no node took the transaction from us, but the message alone can't be
   * trusted (ADR 0009). If the chain has already used the nonce, exactly one transaction did, and a
   * receipt tells whether it was ours.
   */
  async #explainRejection(
    sender: Address,
    nonce: number,
    hash: Hash,
    chain: RuntimeChain,
    rejection: Rejected,
  ): Promise<Verdict> {
    const { read } = chain.rpc
    const confirmed = await read.getTransactionCount({ address: sender, blockTag: 'latest' }).catch(() => undefined)

    if (confirmed !== undefined && nonce < confirmed) {
      try {
        // Checked twice: a load-balanced RPC can report the nonce before it can return the receipt.
        if (await hasReceipt(read, hash)) return { kind: 'ours_on_chain' }
        await sleep(chain.config.pollIntervalMs)
        if (await hasReceipt(read, hash)) return { kind: 'ours_on_chain' }
      } catch {
        return { kind: 'undecided' } // it may be ours: the monitor checks again
      }
      return { kind: 'nonce_used', confirmed }
    }

    switch (rejection.reason) {
      case 'nonce_too_high':
      case 'nonce_too_low': // the chain disagrees or couldn't be read: most likely a lagging RPC
        return { kind: 'retry_later' }
      case 'insufficient_funds':
        return { kind: 'failed', failure: { code: 'INSUFFICIENT_FUNDS', message: rejection.message } }
      default:
        return { kind: 'failed', failure: { code: 'BROADCAST_REJECTED', message: rejection.message } }
    }
  }

  #submitted(tx: TxRecord, attempt: Attempt, outcome: 'accepted' | 'unknown', nonce: number, log: Logger): JobResult {
    this.#deps.store.setAttemptOutcome(attempt.id, outcome)
    this.#deps.store.markSubmitted(tx.id, attempt.hash)
    log.info({ nonce, hash: attempt.hash, outcome }, 'submitted')
    return 'submitted'
  }

  #fail(tx: TxRecord, failure: Failure, log: Logger): JobResult {
    this.#deps.store.markFailed(tx.id, failure.code, failure.message)
    log.warn(failure, 'failed')
    return 'final'
  }

  #chain(chainId: number): RuntimeChain {
    const chain = this.#deps.chains.get(chainId)
    if (!chain) throw new Error(`chain ${chainId} is not enabled`)
    return chain
  }
}

async function hasReceipt(read: PublicClient, hash: Hash): Promise<boolean> {
  try {
    await read.getTransactionReceipt({ hash })
    return true
  } catch (error) {
    if (error instanceof TransactionReceiptNotFoundError) return false
    throw error
  }
}

