describe('broadcast outcomes', () => {
  test('an unanswered broadcast keeps the nonce and leaves the request to the monitor', async () => {
    const rt = await createRuntime(node.url, {
      wrapSenders: () => [
        async () => {
          throw timeoutError()
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0 })
    expect(outcomes(rt, tx.id)).toEqual(['unknown'])
    expect(rt.senders.get(anvil.id, ADDRESS_0).pool.top).toBe(1)
  })

  test('a clear rejection fails the request and gives its nonce to the next one', async () => {
    let sends = 0
    const rt = await createRuntime(node.url, {
      wrapSenders: ([real]) => [
        async (raw) => {
          if (sends++ === 0) throw nodeError('intrinsic gas too low')
          return real(raw)
        },
      ],
    })
    const rejected = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(rejected.id)).toMatchObject({
      status: 'failed',
      error: { code: 'BROADCAST_REJECTED', message: 'intrinsic gas too low' },
    })

    const next = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(next.id)).toMatchObject({ status: 'submitted', nonce: 0 })
  })

  test('"nonce too high" on an unused nonce is retried shortly, with the same nonce', async () => {
    let sends = 0
    const rt = await createRuntime(node.url, {
      wrapSenders: ([real]) => [
        async (raw) => {
          if (sends++ === 0) throw nodeError('nonce too high')
          return real(raw)
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0 })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'accepted'])
  })

  test('gives up after the "nonce too high" retry limit and frees the nonce', async () => {
    const rt = await createRuntime(node.url, {
      worker: { nonceTooHighRetries: 2 },
      wrapSenders: () => [
        async () => {
          throw nodeError('nonce too high')
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'failed', error: { code: 'BROADCAST_REJECTED' } })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'rejected', 'rejected'])
    expect(rt.senders.get(anvil.id, ADDRESS_0).pool.top).toBe(0)
  })

  test('when another tx already used the nonce, resyncs from the chain and retries with a fresh one', async () => {
    const rt = await createRuntime(node.url)
    // Uses nonce 0 behind the pool's back.
    const outsider = createWalletClient({ account: privateKeyToAccount(KEY_0), chain: anvil, transport: http(node.url) })
    await outsider.sendTransaction({ to: ADDRESS_1, value: 1n })

    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 1 })
    expect(outcomes(rt, tx.id)).toEqual(['rejected', 'accepted'])
  })

  test('when our own tx was mined despite an error, counts it as accepted and does not retry', async () => {
    // Like a load balancer that forwards the tx to one backend, then returns another backend's error.
    const rt = await createRuntime(node.url, {
      wrapSenders: ([real]) => [
        async (raw) => {
          await real(raw)
          throw nodeError('nonce too low')
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0 })
    expect(outcomes(rt, tx.id)).toEqual(['accepted'])
    expect(await rt.read.getTransactionCount({ address: ADDRESS_0 })).toBe(1)
  })
})

