import { randomUUID } from 'node:crypto'
import { createTestClient, http, parseGwei, type PublicClient, type TestClient } from 'viem'
import { anvil } from 'viem/chains'
import { withDefaults } from '../../src/config/defaults'
import type { EnabledChain } from '../../src/config/load'
import type { ChainConfig, GasConfig } from '../../src/config/types'
import { createLogger } from '../../src/logger'
import { NoncePool } from '../../src/executor/nonce-pool'
import { createChainRpc, type RuntimeChain, type Sender } from '../../src/executor/rpc'
import { SenderRegistry } from '../../src/executor/senders'
import { buildSigners } from '../../src/signers'
import { openDb } from '../../src/store/db'
import { Store, type NewRequest, type TxRecord } from '../../src/store/store'
import { Monitor } from '../../src/executor/monitor'
import { Worker, type WorkerOptions } from '../../src/executor/worker'
import { ADDRESS_0, ADDRESS_1, KEY_0, KEY_1 } from './keys'

export type RuntimeOptions = {
  chain?: Partial<Omit<ChainConfig, 'chain' | 'gas'>> & { gas?: Partial<GasConfig> }
  worker?: Partial<WorkerOptions>
  /** Replaces the broadcast senders, e.g. to simulate a node that times out. */
  wrapSenders?: (real: Sender[]) => Sender[]
  /** Starts every pool at this nonce instead of reading the chain (for an unreachable RPC). */
  initialNonce?: number
}

export type TestRuntime = {
  store: Store
  worker: Worker
  /** Not started: tests call tick() themselves. */
  monitor: Monitor
  senders: SenderRegistry
  chain: RuntimeChain
  read: PublicClient
  testClient: TestClient
  /** Stores a request from ADDRESS_0 to ADDRESS_1 (unless overridden) and hands it to the worker. */
  submit(overrides?: Partial<NewRequest>): TxRecord
}

/** Everything the worker needs, against an anvil node at `url`, with short test timings. */
export async function createRuntime(url: string, options: RuntimeOptions = {}): Promise<TestRuntime> {
  const base = withDefaults({ chain: anvil, pollIntervalMs: 50, gas: { maxFeePerGasWei: parseGwei('100') } })
  const config: EnabledChain = {
    ...base,
    ...options.chain,
    gas: { ...base.gas, ...options.chain?.gas },
    rpcUrls: [url],
  }
  const rpc = createChainRpc(config)
  const chain: RuntimeChain = {
    config,
    rpc: options.wrapSenders ? { ...rpc, senders: options.wrapSenders(rpc.senders) } : rpc,
  }

  const store = new Store(openDb(':memory:'))
  const signers = buildSigners([KEY_0, KEY_1])
  const senders = new SenderRegistry()
  for (const address of signers.keys()) {
    const pool =
      options.initialNonce === undefined
        ? NoncePool.rebuild({
            confirmed: await rpc.read.getTransactionCount({ address, blockTag: 'latest' }),
            pending: await rpc.read.getTransactionCount({ address, blockTag: 'pending' }),
            held: [],
          })
        : new NoncePool(options.initialNonce)
    senders.add(anvil.id, address, pool)
  }

  const worker = new Worker(
    { store, chains: new Map([[anvil.id, chain]]), signers, senders, logger: createLogger('silent') },
    { broadcastDelayMs: 0, ...options.worker },
  )

  const monitor = new Monitor(
    { store, chain, signers, senders, worker, logger: createLogger('silent') },
    { broadcastDelayMs: 0 },
  )

  return {
    store,
    worker,
    monitor,
    senders,
    chain,
    read: rpc.read,
    testClient: createTestClient({ chain: anvil, mode: 'anvil', transport: http(url) }),
    submit(overrides = {}) {
      const { tx } = store.insertRequest({
        idempotencyKey: randomUUID(),
        requestHash: 'test',
        chainId: anvil.id,
        sender: ADDRESS_0,
        to: ADDRESS_1,
        value: 1n,
        data: '0x',
        ...overrides,
      })
      worker.enqueue(tx.id)
      return tx
    },
  }
}

import { buildApp } from './app'
import { ConfigError } from './config/error'
import { loadConfig, type AppConfig } from './config/load'
import { createLogger } from './logger'
import { verifyChainId } from './executor/rpc'

const config = loadConfigOrExit()
const logger = createLogger(config.logLevel)
await verifyChainsOrExit(config)
logger.info({ chains: [...config.chains.keys()], senders: [...config.signers.keys()] }, 'configuration loaded')

const server = buildApp().listen(config.port, config.host, (error) => {
  if (error) {
    logger.fatal({ err: error }, 'failed to start')
    process.exit(1)
  }
  logger.info({ host: config.host, port: config.port }, 'listening')
})

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    logger.info({ signal }, 'shutting down')
    server.close(() => process.exit(0))
  })
}

function loadConfigOrExit(): AppConfig {
  try {
    return loadConfig(process.env)
  } catch (error) {
    return exitOnConfigError(error)
  }
}

async function verifyChainsOrExit(config: AppConfig): Promise<void> {
  try {
    await Promise.all([...config.chains.values()].map(verifyChainId))
  } catch (error) {
    exitOnConfigError(error)
  }
}

function exitOnConfigError(error: unknown): never {
  if (!(error instanceof ConfigError)) throw error
  console.error(`Configuration error: ${error.message}`)
  process.exit(1)
}

import { keccak256, type Hash, type Hex, type LocalAccount } from 'viem'
import { broadcast, type BroadcastResult } from './broadcast'
import type { RuntimeChain } from './rpc'
import type { Attempt, Store, TxRecord } from '../store/store'
import type { Fees } from '../types'

export type BroadcastOptions = { maxSends: number; delayMs: number }

export type AttemptDraft = { nonce: number; gasLimit: bigint; fees: Fees }

/**
 * Signs an attempt, saves it, then broadcasts it. Saving comes first, so a crash can never lose
 * track of a transaction a node may have (ADR 0003). Only signing or saving can throw.
 */
export async function sendAttempt(
  store: Store,
  chain: RuntimeChain,
  account: LocalAccount,
  tx: TxRecord,
  draft: AttemptDraft,
  options: BroadcastOptions,
): Promise<{ attempt: Attempt; result: BroadcastResult }> {
  const signed = await sign(account, tx, draft)
  const attempt = store.recordAttempt(tx.id, { ...draft, ...signed })
  const result = await broadcast(attempt.raw, chain.rpc.senders, options)
  return { attempt, result }
}

async function sign(account: LocalAccount, tx: TxRecord, draft: AttemptDraft): Promise<{ raw: Hex; hash: Hash }> {
  const common = {
    chainId: tx.chainId,
    to: tx.to,
    value: tx.value,
    data: tx.data,
    nonce: draft.nonce,
    gas: draft.gasLimit,
  }
  const { fees } = draft
  const raw =
    fees.type === 'legacy'
      ? await account.signTransaction({ ...common, type: 'legacy', gasPrice: fees.gasPrice })
      : await account.signTransaction({
          ...common,
          type: 'eip1559',
          maxFeePerGas: fees.maxFeePerGas,
          maxPriorityFeePerGas: fees.maxPriorityFeePerGas,
        })
  return { raw, hash: keccak256(raw) }
}

import { setTimeout as sleep } from 'node:timers/promises'
import { TransactionReceiptNotFoundError, type Address, type Hash, type PublicClient } from 'viem'
import { sendAttempt, type BroadcastOptions } from './attempts'
import { broadcast } from './broadcast'
import { bumpFees, priceFees, readMarketFees } from './gas'
import type { Logger } from '../logger'
import type { RuntimeChain } from './rpc'
import type { SenderRegistry } from './senders'
import type { Signers } from '../config/signers'
import type { Store, TxRecord } from '../store/store'
import type { Fees, Receipt } from '../types'
import type { Worker } from './worker'

export type MonitorOptions = {
  broadcastSends: number
  broadcastDelayMs: number
  /** Polls in a row that must see the nonce used by another tx before NONCE_TAKEN (ADR 0009). */
  nonceTakenPolls: number
}

export type MonitorDeps = {
  store: Store
  chain: RuntimeChain
  signers: Signers
  senders: SenderRegistry
  worker: Worker
  logger: Logger
}

const DEFAULTS: MonitorOptions = { broadcastSends: 3, broadcastDelayMs: 250, nonceTakenPolls: 2 }

/**
 * One per chain. Every pollIntervalMs it checks each submitted request (ADR 0008, layer 4), then
 * lets the worker fill any nonce gap that has been open for stuckAfterMs (ADR 0009).
 */
export class Monitor {
  readonly #deps: MonitorDeps
  readonly #options: MonitorOptions
  readonly #broadcast: BroadcastOptions
  readonly #log: Logger
  /** When each request last had an attempt sent or resent. "Stuck" is measured from here. */
  readonly #lastSentAt = new Map<string, number>()
  /** How many polls in a row have seen each request's nonce used by another transaction. */
  readonly #nonceTakenPolls = new Map<string, number>()
  readonly #stop = new AbortController()
  #loop: Promise<void> | undefined

  constructor(deps: MonitorDeps, options: Partial<MonitorOptions> = {}) {
    this.#deps = deps
    this.#options = { ...DEFAULTS, ...options }
    this.#broadcast = { maxSends: this.#options.broadcastSends, delayMs: this.#options.broadcastDelayMs }
    this.#log = deps.logger.child({ chainId: deps.chain.config.chain.id })
  }

  start(): void {
    this.#loop ??= this.#run()
  }

  async stop(): Promise<void> {
    this.#stop.abort()
    await this.#loop
  }

  async tick(): Promise<void> {
    const { store, chain, signers, worker } = this.#deps
    const chainId = chain.config.chain.id

    // One nonce read per sender per tick, shared by all of its requests.
    const confirmed = new Map<Address, Promise<number>>()
    const confirmedCount = (sender: Address) => {
      if (!confirmed.has(sender)) {
        confirmed.set(sender, chain.rpc.read.getTransactionCount({ address: sender, blockTag: 'latest' }))
      }
      return confirmed.get(sender)!
    }

    for (const tx of store.listByStatus(['submitted'], chainId)) {
      try {
        await this.#check(tx, confirmedCount)
      } catch (error) {
        this.#log.warn({ err: error, txId: tx.id }, 'could not check request')
      }
    }

    for (const sender of signers.keys()) worker.fillGap(chainId, sender, chain.config.stuckAfterMs)
  }

  async #run(): Promise<void> {
    while (!this.#stop.signal.aborted) {
      await this.tick()
      await sleep(this.#deps.chain.config.pollIntervalMs, undefined, { signal: this.#stop.signal }).catch(() => {})
    }
  }

  async #check(tx: TxRecord, confirmedCount: (sender: Address) => Promise<number>): Promise<void> {
    const { store, chain } = this.#deps
    const attempts = store.attempts(tx.id)
    const live = attempts.filter((attempt) => attempt.outcome !== 'rejected')

    // 1. Mined. Any attempt can be the one: the original can be mined after a replacement was sent.
    for (const attempt of live) {
      const receipt = await findReceipt(chain.rpc.read, attempt.hash)
      if (receipt) {
        if (store.markMined(tx.id, receipt)) this.#finished(tx, { status: receipt.status, hash: receipt.transactionHash })
        return
      }
    }

    // 2. The nonce was used by another transaction, so ours can never be mined. Needs two polls
    // in a row: a load-balanced RPC can report the new nonce before it can return the receipt.
    const confirmed = await confirmedCount(tx.sender)
    if (tx.nonce! < confirmed) {
      const polls = (this.#nonceTakenPolls.get(tx.id) ?? 0) + 1
      this.#nonceTakenPolls.set(tx.id, polls)
      if (polls < this.#options.nonceTakenPolls) return
      this.#deps.senders.get(tx.chainId, tx.sender).pool.reset(confirmed)
      if (store.markFailed(tx.id, 'NONCE_TAKEN', `nonce ${tx.nonce} was used by another transaction`)) {
        this.#finished(tx, { status: 'failed', code: 'NONCE_TAKEN' })
      }
      return
    }
    this.#nonceTakenPolls.delete(tx.id)

    // 3. Stuck: replace it with higher fees, or once that's not possible, resend it unchanged.
    // A broadcast transaction is never failed because time ran out (ADR 0008).
    const latest = attempts[attempts.length - 1]
    const lastSent = this.#lastSentAt.get(tx.id) ?? Date.parse(latest.createdAt)
    if (Date.now() - lastSent < chain.config.stuckAfterMs) return
    this.#lastSentAt.set(tx.id, Date.now())

    const bumpsLeft = attempts.length - 1 < chain.config.gas.maxBumps
    if (bumpsLeft && (await this.#replace(tx, latest.fees))) return
    const resend = live[live.length - 1]
    await broadcast(resend.raw, chain.rpc.senders, this.#broadcast)
    this.#log.info({ txId: tx.id, hash: resend.hash }, 'stuck: resent unchanged')
  }

  /** Sends a replacement at the same nonce with higher fees. Returns false when the fee cap prevents it. */
  async #replace(tx: TxRecord, previous: Fees): Promise<boolean> {
    const { store, chain, signers } = this.#deps
    const { gas } = chain.config
    const market = priceFees(await readMarketFees(chain.rpc.read, gas.type), gas)
    const fees = bumpFees(previous, market === 'above_cap' ? null : market, gas)
    if (fees === 'above_cap') return false

    const draft = { nonce: tx.nonce!, gasLimit: tx.gasLimit!, fees }
    const { attempt, result } = await sendAttempt(store, chain, signers.get(tx.sender)!, tx, draft, this.#broadcast)
    if (result.outcome === 'rejected') {
      // The earlier attempt is still valid. The next bump starts from this higher fee (ADR 0008).
      store.setAttemptOutcome(attempt.id, 'rejected')
      this.#log.info({ txId: tx.id, hash: attempt.hash, nodeMessage: result.message }, 'stuck: replacement rejected')
      return true
    }
    store.setAttemptOutcome(attempt.id, result.outcome)
    store.markSubmitted(tx.id, attempt.hash)
    this.#log.info({ txId: tx.id, hash: attempt.hash, outcome: result.outcome }, 'stuck: replaced with higher fees')
    return true
  }

  #finished(tx: TxRecord, fields: Record<string, unknown>): void {
    this.#lastSentAt.delete(tx.id)
    this.#nonceTakenPolls.delete(tx.id)
    this.#log.info({ txId: tx.id, ...fields }, 'final')
    this.#deps.worker.release(tx)
  }
}

async function findReceipt(read: PublicClient, hash: Hash): Promise<Receipt | null> {
  try {
    const receipt = await read.getTransactionReceipt({ hash })
    return {
      transactionHash: receipt.transactionHash,
      blockNumber: receipt.blockNumber,
      blockHash: receipt.blockHash,
      gasUsed: receipt.gasUsed,
      effectiveGasPrice: receipt.effectiveGasPrice,
      status: receipt.status,
    }
  } catch (error) {
    if (error instanceof TransactionReceiptNotFoundError) return null
    throw error
  }
}

import type { Address, LocalAccount } from 'viem'
import { sendAttempt, type BroadcastOptions } from './attempts'
import { classifyNodeMessage, describeSendError, isTransportError } from './broadcast'
import { estimateGasLimit, priceFees, readMarketFees } from './gas'
import type { Logger } from '../logger'
import type { RuntimeChain } from './rpc'
import type { SenderRegistry, SenderState } from './senders'
import type { Signers } from '../config/signers'
import type { Store, TxRecord } from '../store/store'
import type { FailureCode, Fees } from '../types'

export type WorkerOptions = {
  broadcastSends: number
  broadcastDelayMs: number
}

export type WorkerDeps = {
  store: Store
  chains: Map<number, RuntimeChain>
  signers: Signers
  senders: SenderRegistry
  logger: Logger
}

const DEFAULTS: WorkerOptions = { broadcastSends: 3, broadcastDelayMs: 250 }

type Prepared = { gasLimit: bigint; fees: Fees }
type Failure = { code: FailureCode; message: string }

/** How a job ended: final (failed), or submitted and now watched by the monitor. */
type JobResult = 'final' | 'submitted'

/**
 * Takes each request through: estimate gas → price fees → take nonce → sign → save → broadcast.
 * Works on at most maxInFlightPerSender requests per sender at a time (ADR 0012).
 */
export class Worker {
  readonly #deps: WorkerDeps
  readonly #broadcast: BroadcastOptions
  readonly #running = new Set<Promise<void>>()

  constructor(deps: WorkerDeps, options: Partial<WorkerOptions> = {}) {
    this.#deps = deps
    const { broadcastSends, broadcastDelayMs } = { ...DEFAULTS, ...options }
    this.#broadcast = { maxSends: broadcastSends, delayMs: broadcastDelayMs }
  }

  /** Queues a stored request. It starts as soon as its sender has a free slot. */
  enqueue(txId: string): void {
    const tx = this.#deps.store.get(txId)
    if (!tx) throw new Error(`unknown request ${txId}`)
    this.#deps.senders.get(tx.chainId, tx.sender).queue.push(txId)
    this.#pump(tx.chainId, tx.sender)
  }

  /** Frees the slot of a submitted request that has become final. Called by the monitor. */
  release(tx: TxRecord): void {
    this.#deps.senders.get(tx.chainId, tx.sender).active.delete(tx.id)
    this.#pump(tx.chainId, tx.sender)
  }

  /**
   * Sends 0 ETH from the sender to itself at its lowest nonce gap, once the gap has been open for
   * `minAgeMs` (ADR 0009). Same path as a request, except the nonce comes from takeGap and no slot
   * is used: the requests stuck behind the gap may be holding every slot.
   */
  fillGap(chainId: number, sender: Address, minAgeMs: number): void {
    const state = this.#deps.senders.get(chainId, sender)
    const nonce = state.pool.takeGap(minAgeMs)
    if (nonce === undefined) return
    const tx = this.#deps.store.insertGapFill(chainId, sender)
    this.#track(this.#process(tx.id, state, nonce))
  }

  /** Resolves once no request is being processed. Requests waiting for a slot don't count. */
  async idle(): Promise<void> {
    while (this.#running.size > 0) await Promise.allSettled([...this.#running])
  }

  #pump(chainId: number, sender: Address): void {
    const state = this.#deps.senders.get(chainId, sender)
    const slots = this.#chain(chainId).config.maxInFlightPerSender
    while (state.active.size < slots && state.queue.length > 0) {
      const txId = state.queue.shift()!
      state.active.add(txId)
      this.#track(
        this.#process(txId, state).then((result) => {
          if (result === 'final') this.release(this.#deps.store.get(txId)!)
        }),
      )
    }
  }

  #track(job: Promise<unknown>): void {
    const tracked: Promise<void> = job.then(
      () => undefined,
      () => undefined,
    )
    this.#running.add(tracked)
    void tracked.finally(() => this.#running.delete(tracked))
  }

  /** `gapNonce` is set for a gap fill, which takes its nonce up front. */
  async #process(txId: string, state: SenderState, gapNonce?: number): Promise<JobResult> {
    const { store } = this.#deps
    const tx = store.get(txId)!
    const log = this.#deps.logger.child({ txId, chainId: tx.chainId, sender: tx.sender, kind: tx.kind })
    try {
      const chain = this.#chain(tx.chainId)
      const account = this.#deps.signers.get(tx.sender)
      if (!account) throw new Error(`no signer for ${tx.sender}`)

      const prepared = await prepare(tx, chain)
      if ('code' in prepared) {
        if (gapNonce !== undefined) state.pool.rollback(gapNonce)
        return this.#fail(tx, prepared, log)
      }
      return await this.#submit(tx, prepared, chain, account, state, log, gapNonce)
    } catch (error) {
      // A bug or an unexpected error. If a node may have one of the attempts, the monitor takes
      // over, just as after a restart (ADR 0003).
      log.error({ err: error }, 'unexpected error')
      const live = store.attempts(tx.id).filter((attempt) => attempt.outcome !== 'rejected')
      if (live.length > 0) {
        store.markSubmitted(tx.id, live[live.length - 1].hash)
        return 'submitted'
      }
      if (gapNonce !== undefined) state.pool.rollback(gapNonce)
      const message = error instanceof Error ? error.message : String(error)
      return this.#fail(tx, { code: 'INTERNAL_ERROR', message }, log)
    }
  }

  /** Takes a nonce as late as possible, then signs, saves and broadcasts (ADR 0009). */
  async #submit(
    tx: TxRecord,
    prepared: Prepared,
    chain: RuntimeChain,
    account: LocalAccount,
    state: SenderState,
    log: Logger,
    gapNonce?: number,
  ): Promise<JobResult> {
    const { store } = this.#deps
    const nonce = gapNonce ?? state.pool.take()
    let sent: Awaited<ReturnType<typeof sendAttempt>>
    try {
      sent = await sendAttempt(store, chain, account, tx, { nonce, ...prepared }, this.#broadcast)
    } catch (error) {
      state.pool.rollback(nonce) // signing or saving failed: nothing was sent
      throw error
    }
    const { attempt, result } = sent

    if (result.outcome !== 'rejected') {
      store.setAttemptOutcome(attempt.id, result.outcome)
      store.markSubmitted(tx.id, attempt.hash)
      log.info({ nonce, hash: attempt.hash, outcome: result.outcome }, 'submitted')
      return 'submitted'
    }

    // Every send was answered with a rejection, so no node has the transaction: give the nonce
    // back, then drop any nonce the chain has already used (ADR 0009).
    store.setAttemptOutcome(attempt.id, 'rejected')
    state.pool.rollback(nonce)
    await this.#resync(state, chain, tx.sender, log)
    const code = result.reason === 'insufficient_funds' ? 'INSUFFICIENT_FUNDS' : 'BROADCAST_REJECTED'
    return this.#fail(tx, { code, message: result.message }, log)
  }

  /** Drops available nonces the chain has already used, so an out-of-sync pool heals itself. */
  async #resync(state: SenderState, chain: RuntimeChain, sender: Address, log: Logger): Promise<void> {
    try {
      state.pool.reset(await chain.rpc.read.getTransactionCount({ address: sender, blockTag: 'latest' }))
    } catch (error) {
      log.warn({ err: error }, 'could not read the nonce to resync the pool')
    }
  }

  #fail(tx: TxRecord, failure: Failure, log: Logger): JobResult {
    this.#deps.store.markFailed(tx.id, failure.code, failure.message)
    log.warn(failure, 'failed')
    return 'final'
  }

  #chain(chainId: number): RuntimeChain {
    const chain = this.#deps.chains.get(chainId)
    if (!chain) throw new Error(`chain ${chainId} is not enabled`)
    return chain
  }
}

/** Gas limit and fees. viem already retries each read (ADR 0008), so a failure here ends the request. */
async function prepare(tx: TxRecord, chain: RuntimeChain): Promise<Prepared | Failure> {
  const { gas } = chain.config
  try {
    const gasLimit = await estimateGasLimit(chain.rpc.read, tx, gas.gasLimitBufferPercent)
    const fees = priceFees(await readMarketFees(chain.rpc.read, gas.type), gas)
    if (fees === 'above_cap') {
      return { code: 'FEE_ABOVE_CAP', message: `base fee plus tip is above the cap of ${gas.maxFeePerGasWei} wei` }
    }
    return { gasLimit, fees }
  } catch (error) {
    const answer = describeSendError(error)
    if (answer.answered) {
      const funds = classifyNodeMessage(answer.message) === 'insufficient_funds'
      return { code: funds ? 'INSUFFICIENT_FUNDS' : 'ESTIMATION_REVERTED', message: answer.message }
    }
    if (isTransportError(error)) return { code: 'RPC_UNAVAILABLE', message: 'the RPC could not be reached' }
    throw error
  }
}

import type { LevelWithSilent } from 'pino'
import { buildSigners, type Signers } from './signers'
import { CHAIN_FILES } from './chains'
import { withDefaults } from './defaults'
import { parseEnv, type Env } from './env'
import { ConfigError } from './error'
import type { ChainConfig, ChainFile } from './types'

export type EnabledChain = ChainConfig & { rpcUrls: string[] }

export type AppConfig = {
  chains: Map<number, EnabledChain>
  signers: Signers
  host: string
  port: number
  dbPath: string
  logLevel: LevelWithSilent
}

/**
 * Reads and checks everything the service needs to start (ADRs 0005 and 0006). Checking each
 * RPC's eth_chainId needs the network, so it happens later, at startup.
 *
 * Removes SIGNER_PRIVATE_KEYS from `env` once read: after this, the keys only live inside the
 * signer accounts.
 */
export function loadConfig(env: Env, files: ChainFile[] = CHAIN_FILES): AppConfig {
  const { rpcUrls, privateKeys, ...server } = parseEnv(env)
  const signers = buildSigners(privateKeys)
  delete env.SIGNER_PRIVATE_KEYS

  const chains = new Map<number, EnabledChain>()
  for (const [chainId, urls] of rpcUrls) {
    const file = files.find((candidate) => candidate.chain.id === chainId)
    if (!file) {
      throw new ConfigError(
        `RPC_URL_${chainId} is set, but src/config/chains/ has no config file for chain ${chainId}`,
      )
    }
    chains.set(chainId, { ...withDefaults(file), rpcUrls: urls })
  }

  return { chains, signers, ...server }
}

import { randomUUID } from 'node:crypto'
import { createTestClient, http, parseGwei, type PublicClient, type TestClient } from 'viem'
import { anvil } from 'viem/chains'
import { withDefaults } from '../../src/config/defaults'
import type { EnabledChain } from '../../src/config/load'
import type { ChainConfig, GasConfig } from '../../src/config/types'
import { Monitor } from '../../src/executor/monitor'
import { NoncePool } from '../../src/executor/nonce-pool'
import { createChainRpc, type RuntimeChain, type Sender } from '../../src/executor/rpc'
import { SenderRegistry } from '../../src/executor/senders'
import { Worker, type WorkerOptions } from '../../src/executor/worker'
import { createLogger } from '../../src/logger'
import { buildSigners } from '../../src/config/signers'
import { openDb } from '../../src/store/db'
import { Store, type NewRequest, type TxRecord } from '../../src/store/store'
import { ADDRESS_0, ADDRESS_1, KEY_0, KEY_1 } from './keys'

export type RuntimeOptions = {
  chain?: Partial<Omit<ChainConfig, 'chain' | 'gas'>> & { gas?: Partial<GasConfig> }
  worker?: Partial<WorkerOptions>
  /** Replaces the broadcast senders, e.g. to simulate a node that times out. */
  wrapSenders?: (real: Sender[]) => Sender[]
  /** Starts every pool at this nonce instead of reading the chain (for an unreachable RPC). */
  initialNonce?: number
}

export type TestRuntime = {
  store: Store
  worker: Worker
  /** Not started: tests call tick() themselves. */
  monitor: Monitor
  senders: SenderRegistry
  chain: RuntimeChain
  read: PublicClient
  testClient: TestClient
  /** Stores a request from ADDRESS_0 to ADDRESS_1 (unless overridden) and hands it to the worker. */
  submit(overrides?: Partial<NewRequest>): TxRecord
}

/** Everything the worker needs, against an anvil node at `url`, with short test timings. */
export async function createRuntime(url: string, options: RuntimeOptions = {}): Promise<TestRuntime> {
  const base = withDefaults({ chain: anvil, pollIntervalMs: 50, gas: { maxFeePerGasWei: parseGwei('100') } })
  const config: EnabledChain = {
    ...base,
    ...options.chain,
    gas: { ...base.gas, ...options.chain?.gas },
    rpcUrls: [url],
  }
  const rpc = createChainRpc(config)
  const chain: RuntimeChain = {
    config,
    rpc: options.wrapSenders ? { ...rpc, senders: options.wrapSenders(rpc.senders) } : rpc,
  }

  const store = new Store(openDb(':memory:'))
  const signers = buildSigners([KEY_0, KEY_1])
  const senders = new SenderRegistry()
  for (const address of signers.keys()) {
    const pool =
      options.initialNonce === undefined
        ? NoncePool.rebuild({
            confirmed: await rpc.read.getTransactionCount({ address, blockTag: 'latest' }),
            pending: await rpc.read.getTransactionCount({ address, blockTag: 'pending' }),
            held: [],
          })
        : new NoncePool(options.initialNonce)
    senders.add(anvil.id, address, pool)
  }

  const worker = new Worker(
    { store, chains: new Map([[anvil.id, chain]]), signers, senders, logger: createLogger('silent') },
    { broadcastDelayMs: 0, ...options.worker },
  )

  const monitor = new Monitor(
    { store, chain, signers, senders, worker, logger: createLogger('silent') },
    { broadcastDelayMs: 0 },
  )

  return {
    store,
    worker,
    monitor,
    senders,
    chain,
    read: rpc.read,
    testClient: createTestClient({ chain: anvil, mode: 'anvil', transport: http(url) }),
    submit(overrides = {}) {
      const { tx } = store.insertRequest({
        idempotencyKey: randomUUID(),
        requestHash: 'test',
        chainId: anvil.id,
        sender: ADDRESS_0,
        to: ADDRESS_1,
        value: 1n,
        data: '0x',
        ...overrides,
      })
      worker.enqueue(tx.id)
      return tx
