import { createWalletClient, http, parseEther, parseGwei, type Address } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { anvil } from 'viem/chains'
import { afterEach, beforeEach, describe, expect, test } from 'vitest'
import { startAnvil, unreachableUrl, type AnvilNode } from '../helpers/anvil'
import { ADDRESS_0, ADDRESS_1, KEY_0 } from '../helpers/keys'
import { nodeError, timeoutError } from '../helpers/rpc-errors'
import { createRuntime, type TestRuntime } from '../helpers/runtime'

let node: AnvilNode

beforeEach(async () => {
  node = await startAnvil()
})

afterEach(() => node.stop())

function outcomes(rt: TestRuntime, txId: string) {
  return rt.store.attempts(txId).map((attempt) => attempt.outcome)
}

describe('a request that reaches the chain', () => {
  test('is estimated, signed, saved, broadcast and marked submitted', async () => {
    const rt = await createRuntime(node.url)
    const tx = rt.submit()
    await rt.worker.idle()

    const [attempt] = rt.store.attempts(tx.id)
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0, gasLimit: 25_200n, hash: attempt.hash })
    expect(attempt.outcome).toBe('accepted')
    // anvil mines on arrival, so the chain has it under the saved hash
    expect(await rt.read.getTransactionReceipt({ hash: attempt.hash })).toMatchObject({ status: 'success' })
  })

  test('gives concurrent requests from one sender distinct nonces', async () => {
    const rt = await createRuntime(node.url)
    const txs = Array.from({ length: 5 }, () => rt.submit())
    await rt.worker.idle()

    expect(txs.map((tx) => rt.store.get(tx.id)!.nonce).sort((a, b) => a! - b!)).toEqual([0, 1, 2, 3, 4])
    expect(await rt.read.getTransactionCount({ address: ADDRESS_0 })).toBe(5)
  })

  test('works on at most maxInFlightPerSender requests per sender, and starts the next when one finishes', async () => {
    const rt = await createRuntime(node.url, { chain: { maxInFlightPerSender: 2 } })
    await rt.testClient.setAutomine(false) // keep them submitted
    const txs = Array.from({ length: 3 }, () => rt.submit())
    await rt.worker.idle()
    expect(txs.map((tx) => rt.store.get(tx.id)!.status)).toEqual(['submitted', 'submitted', 'queued'])

    // Stand-in for the monitor finishing the first request.
    rt.store.markFailed(txs[0].id, 'NONCE_TAKEN', 'test')
    rt.worker.release(rt.store.get(txs[0].id)!)
    await rt.worker.idle()
    expect(rt.store.get(txs[2].id)!.status).toBe('submitted')
  })
})

describe('failures before anything is signed', () => {
  test('a call that would revert fails with ESTIMATION_REVERTED and uses no nonce', async () => {
    const rt = await createRuntime(node.url)
    const reverter: Address = '0x000000000000000000000000000000000000dEaD'
    await rt.testClient.setCode({ address: reverter, bytecode: '0x60006000fd' }) // REVERT(0, 0)
    const failed = rt.submit({ to: reverter })
    await rt.worker.idle()
    expect(rt.store.get(failed.id)).toMatchObject({ status: 'failed', error: { code: 'ESTIMATION_REVERTED' } })
    expect(rt.store.attempts(failed.id)).toEqual([])

    const next = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(next.id)).toMatchObject({ status: 'submitted', nonce: 0 })
  })

  test('a base fee above the cap fails with FEE_ABOVE_CAP', async () => {
    const rt = await createRuntime(node.url)
    await rt.testClient.setNextBlockBaseFeePerGas({ baseFeePerGas: parseGwei('200') })
    await rt.testClient.mine({ blocks: 1 })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'failed', error: { code: 'FEE_ABOVE_CAP' } })
    expect(rt.store.attempts(tx.id)).toEqual([])
  })

  test('a sender without funds fails with INSUFFICIENT_FUNDS and keeps its nonce free', async () => {
    const rt = await createRuntime(node.url)
    await rt.testClient.setBalance({ address: ADDRESS_1, value: 0n })
    const broke = rt.submit({ sender: ADDRESS_1, to: ADDRESS_0 })
    await rt.worker.idle()
    expect(rt.store.get(broke.id)).toMatchObject({ status: 'failed', error: { code: 'INSUFFICIENT_FUNDS' } })

    await rt.testClient.setBalance({ address: ADDRESS_1, value: parseEther('1') })
    const funded = rt.submit({ sender: ADDRESS_1, to: ADDRESS_0 })
    await rt.worker.idle()
    expect(rt.store.get(funded.id)).toMatchObject({ status: 'submitted', nonce: 0 })
  })

  test('an unreachable RPC fails with RPC_UNAVAILABLE once viem stops retrying', async () => {
    const rt = await createRuntime(await unreachableUrl(), { initialNonce: 0 })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'failed', error: { code: 'RPC_UNAVAILABLE' } })
    expect(rt.store.attempts(tx.id)).toEqual([])
  })
})

describe('broadcast outcomes', () => {
  test('an unanswered broadcast keeps the nonce and leaves the request to the monitor', async () => {
    const rt = await createRuntime(node.url, {
      wrapSenders: () => [
        async () => {
          throw timeoutError()
        },
      ],
    })
    const tx = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(tx.id)).toMatchObject({ status: 'submitted', nonce: 0 })
    expect(outcomes(rt, tx.id)).toEqual(['unknown'])
    expect(rt.senders.get(anvil.id, ADDRESS_0).pool.top).toBe(1)
  })

  test('a clear rejection fails the request and gives its nonce to the next one', async () => {
    let sends = 0
    const rt = await createRuntime(node.url, {
      wrapSenders: ([real]) => [
        async (raw) => {
          if (sends++ === 0) throw nodeError('intrinsic gas too low')
          return real(raw)
        },
      ],
    })
    const rejected = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(rejected.id)).toMatchObject({
      status: 'failed',
      error: { code: 'BROADCAST_REJECTED', message: 'intrinsic gas too low' },
    })

    const next = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(next.id)).toMatchObject({ status: 'submitted', nonce: 0 })
  })

  test('when another tx already used the nonce, fails and resyncs the pool so the next request succeeds', async () => {
    const rt = await createRuntime(node.url)
    // Uses nonce 0 behind the pool's back.
    const outsider = createWalletClient({ account: privateKeyToAccount(KEY_0), chain: anvil, transport: http(node.url) })
    await outsider.sendTransaction({ to: ADDRESS_1, value: 1n })

    const collided = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(collided.id)).toMatchObject({
      status: 'failed',
      error: { code: 'BROADCAST_REJECTED', message: 'nonce too low' },
    })

    const next = rt.submit()
    await rt.worker.idle()
    expect(rt.store.get(next.id)).toMatchObject({ status: 'submitted', nonce: 1 })
  })
})

import { HttpRequestError, InvalidInputRpcError, RpcRequestError, TimeoutError, type Hash, type Hex } from 'viem'
import { describe, expect, test } from 'vitest'
import { broadcast, classifyNodeMessage, describeSendError, isTransportError } from '../../src/executor/broadcast'
import type { Sender } from '../../src/executor/rpc'

const RAW = '0x02f86b' as Hex
const HASH = `0x${'a'.repeat(64)}` as Hash

// The shapes viem produces for each case, as observed against anvil.
function nodeError(message: string) {
  return new InvalidInputRpcError(new RpcRequestError({ body: {}, error: { code: -32000, message }, url: 'http://node' }))
}
const timeout = () => new TimeoutError({ body: {}, url: 'http://node' })

describe('describeSendError', () => {
  test('a JSON-RPC error response is an answer, with the node message', () => {
    expect(describeSendError(nodeError('nonce too low'))).toEqual({ answered: true, message: 'nonce too low' })
  })

  test.each([
    ['a timeout', timeout()],
    ['an HTTP 429', new HttpRequestError({ url: 'http://node', status: 429, body: {} })],
    ['an HTTP 502', new HttpRequestError({ url: 'http://node', status: 502, body: {} })],
    ['a refused connection', new HttpRequestError({ url: 'http://node', body: {}, details: 'fetch failed' })],
    ['a non-viem error', new Error('socket hang up')],
  ])('%s is not an answer', (_case, error) => {
    expect(describeSendError(error)).toEqual({ answered: false })
  })
})

describe('isTransportError', () => {
  test.each([
    ['a timeout', timeout(), true],
    ['an HTTP 502', new HttpRequestError({ url: 'http://node', status: 502, body: {} }), true],
    ['a refused connection', new HttpRequestError({ url: 'http://node', body: {}, details: 'fetch failed' }), true],
    ['a node answer', nodeError('execution reverted'), false],
    ['a non-viem error', new Error('chain has no base fee'), false],
  ])('%s → %s', (_case, error, expected) => {
    expect(isTransportError(error)).toBe(expected)
  })
})

describe('classifyNodeMessage', () => {
  test.each([
    ['already known', 'already_known'], // geth
    ['transaction already imported', 'already_known'], // anvil
    ['AlreadyKnown', 'already_known'], // nethermind
    ['Known transaction', 'already_known'],
    ['nonce too low', 'nonce_too_low'],
    ['nonce too low: next nonce 5, tx nonce 3', 'nonce_too_low'],
    ['nonce too high', 'nonce_too_high'],
    ['insufficient funds for gas * price + value: balance 0, tx cost 21000', 'insufficient_funds'],
    ['Insufficient funds for gas * price + value', 'insufficient_funds'], // anvil
    ['replacement transaction underpriced', 'other'],
    ['intrinsic gas too low', 'other'],
  ])('"%s" → %s', (message, expected) => {
    expect(classifyNodeMessage(message)).toBe(expected)
  })
})

describe('broadcast', () => {
  // A fake RPC per URL: each call runs the next scripted response and is recorded.
  function nodes(...scripts: Array<Array<'accept' | 'timeout' | string>>) {
    const calls: Array<{ url: number; raw: Hex }> = []
    const senders: Sender[] = scripts.map((script, url) => async (raw) => {
      calls.push({ url, raw })
      const response = script.shift()
      if (response === 'accept') return HASH
      if (response === 'timeout') throw timeout()
      throw nodeError(response ?? 'no scripted response')
    })
    return { senders, calls }
  }

  test('an accepted first send is accepted', async () => {
    const { senders, calls } = nodes(['accept'], [])
    expect(await broadcast(RAW, senders, { delayMs: 0 })).toEqual({ outcome: 'accepted' })
    expect(calls).toEqual([{ url: 0, raw: RAW }])
  })

  test('"already known" counts as accepted', async () => {
    const { senders } = nodes(['transaction already imported'])
    expect(await broadcast(RAW, senders, { delayMs: 0 })).toEqual({ outcome: 'accepted' })
  })

  test('after an unanswered send, moves to the next URL', async () => {
    const { senders, calls } = nodes(['timeout'], ['accept'])
    expect(await broadcast(RAW, senders, { delayMs: 0 })).toEqual({ outcome: 'accepted' })
    expect(calls.map((call) => call.url)).toEqual([0, 1])
  })

  test('a clear rejection on the first send is a rejection, and nothing more is sent', async () => {
    const { senders, calls } = nodes(['insufficient funds for gas * price + value'], ['accept'])
    expect(await broadcast(RAW, senders, { delayMs: 0 })).toEqual({
      outcome: 'rejected',
      reason: 'insufficient_funds',
      message: 'insufficient funds for gas * price + value',
    })
    expect(calls.map((call) => call.url)).toEqual([0])
  })

  test('a rejection after an unanswered send is unknown: the first send may have landed', async () => {
    const { senders, calls } = nodes(['timeout'], ['nonce too low'])
    expect(await broadcast(RAW, senders, { delayMs: 0 })).toEqual({ outcome: 'unknown' })
    expect(calls.map((call) => call.url)).toEqual([0, 1])
  })

  test('is unknown when no send is answered, cycling through the URLs', async () => {
    const { senders, calls } = nodes(['timeout', 'timeout'], ['timeout'])
    expect(await broadcast(RAW, senders, { maxSends: 3, delayMs: 0 })).toEqual({ outcome: 'unknown' })
    expect(calls.map((call) => call.url)).toEqual([0, 1, 0])
  })
})

