  add('no-attempt-yet')
  attempt(add('other-sender', { sender: ADDRESS_1 }).id, 9)
  attempt(add('other-chain', { chainId: 1 }).id, 8)

  expect(store.heldNonces(31337, ADDRESS_0)).toEqual([3, 4])
