import type { GasConfig } from '../../src/config/types'
import { applyGasBuffer, bumpFees, priceFees } from '../../src/executor/gas'

const GAS: GasConfig = {
  type: 'eip1559',
  gasLimitBufferPercent: 20,
  baseFeeMultiplier: 2,
  minPriorityFeeWei: 0n,
