1	import type { Address, LocalAccount } from 'viem'
2	import type { Signers } from '../config/signers'
3	import type { Logger } from '../logger'
4	import type { Store, TxRecord } from '../store/store'
5	import type { FailureCode, Fees } from '../types'
6	import { sendAttempt, type BroadcastOptions } from './attempts'
7	import { classifyNodeMessage, describeSendError, isTransportError } from './broadcast'
8	import { estimateGasLimit, priceFees, readMarketFees } from './gas'
9	import type { RuntimeChain } from './rpc'
10	import type { SenderRegistry, SenderState } from './senders'
11	
12	export type WorkerOptions = {
13	  broadcastSends: number
14	  broadcastDelayMs: number
15	}
16	
17	export type WorkerDeps = {
18	  store: Store
19	  chains: Map<number, RuntimeChain>
20	  signers: Signers
21	  senders: SenderRegistry
22	  logger: Logger
23	}
24	
25	const DEFAULTS: WorkerOptions = { broadcastSends: 3, broadcastDelayMs: 250 }
26	
27	type Prepared = { gasLimit: bigint; fees: Fees }
28	type Failure = { code: FailureCode; message: string }
29	
30	/** How a job ended: final (failed), or submitted and now watched by the monitor. */
31	type JobResult = 'final' | 'submitted'
32	
33	/**
34	 * Takes each request through: estimate gas → price fees → take nonce → sign → save → broadcast.
35	 * Works on at most maxInFlightPerSender requests per sender at a time (ADR 0012).
36	 */
37	export class Worker {
38	  readonly #deps: WorkerDeps
39	  readonly #broadcast: BroadcastOptions
40	  readonly #running = new Set<Promise<void>>()
41	
42	  constructor(deps: WorkerDeps, options: Partial<WorkerOptions> = {}) {
43	    this.#deps = deps
44	    const { broadcastSends, broadcastDelayMs } = { ...DEFAULTS, ...options }
45	    this.#broadcast = { maxSends: broadcastSends, delayMs: broadcastDelayMs }
46	  }
47	
48	  /** Queues a stored request. It starts as soon as its sender has a free slot. */
49	  enqueue(txId: string): void {
50	    const tx = this.#deps.store.get(txId)
51	    if (!tx) throw new Error(`unknown request ${txId}`)
52	    this.#deps.senders.get(tx.chainId, tx.sender).queue.push(txId)
53	    this.#pump(tx.chainId, tx.sender)
54	  }
55	
56	  /** Frees the slot of a submitted request that has become final. Called by the monitor. */
57	  release(tx: TxRecord): void {
58	    this.#deps.senders.get(tx.chainId, tx.sender).active.delete(tx.id)
59	    this.#pump(tx.chainId, tx.sender)
60	  }
61	
62	  /**
63	   * Sends 0 ETH from the sender to itself at its lowest nonce gap, once the gap has been open for
64	   * `minAgeMs` (ADR 0009). Same path as a request, except the nonce comes from takeGap and no slot
65	   * is used: the requests stuck behind the gap may be holding every slot.
66	   */
67	  fillGap(chainId: number, sender: Address, minAgeMs: number): void {
68	    const state = this.#deps.senders.get(chainId, sender)
69	    const nonce = state.pool.takeGap(minAgeMs)
70	    if (nonce === undefined) return
71	    const tx = this.#deps.store.insertGapFill(chainId, sender)
72	    this.#track(this.#process(tx.id, state, nonce))
73	  }
74	
75	  /** Resolves once no request is being processed. Requests waiting for a slot don't count. */
76	  async idle(): Promise<void> {
77	    while (this.#running.size > 0) await Promise.allSettled([...this.#running])
78	  }
79	
80	  #pump(chainId: number, sender: Address): void {
81	    const state = this.#deps.senders.get(chainId, sender)
82	    const slots = this.#chain(chainId).config.maxInFlightPerSender
83	    while (state.active.size < slots && state.queue.length > 0) {
84	      const txId = state.queue.shift()!
85	      state.active.add(txId)
86	      this.#track(
87	        this.#process(txId, state).then((result) => {
88	          if (result === 'final') this.release(this.#deps.store.get(txId)!)
89	        }),
90	      )
91	    }
92	  }
93	
94	  #track(job: Promise<unknown>): void {
95	    const tracked: Promise<void> = job.then(
96	      () => undefined,
97	      () => undefined,
98	    )
99	    this.#running.add(tracked)
100	    void tracked.finally(() => this.#running.delete(tracked))
101	  }
102	
103	  /** `gapNonce` is set for a gap fill, which takes its nonce up front. */
104	  async #process(txId: string, state: SenderState, gapNonce?: number): Promise<JobResult> {
105	    const { store } = this.#deps
106	    const tx = store.get(txId)!
107	    const log = this.#deps.logger.child({ txId, chainId: tx.chainId, sender: tx.sender, kind: tx.kind })
108	    try {
109	      const chain = this.#chain(tx.chainId)
110	      const account = this.#deps.signers.get(tx.sender)
111	      if (!account) throw new Error(`no signer for ${tx.sender}`)
112	
113	      const prepared = await prepare(tx, chain)
114	      if ('code' in prepared) {
115	        if (gapNonce !== undefined) state.pool.rollback(gapNonce)
116	        return this.#fail(tx, prepared, log)
117	      }
118	      return await this.#submit(tx, prepared, chain, account, state, log, gapNonce)
119	    } catch (error) {
120	      // A bug or an unexpected error. If a node may have one of the attempts, the monitor takes
121	      // over, just as after a restart (ADR 0003).
122	      log.error({ err: error }, 'unexpected error')
123	      const live = store.attempts(tx.id).filter((attempt) => attempt.outcome !== 'rejected')
124	      if (live.length > 0) {
125	        store.markSubmitted(tx.id, live[live.length - 1].hash)
126	        return 'submitted'
127	      }
128	      if (gapNonce !== undefined) state.pool.rollback(gapNonce)
129	      const message = error instanceof Error ? error.message : String(error)
130	      return this.#fail(tx, { code: 'INTERNAL_ERROR', message }, log)
131	    }
132	  }
133	
134	  /** Takes a nonce as late as possible, then signs, saves and broadcasts (ADR 0009). */
135	  async #submit(
136	    tx: TxRecord,
137	    prepared: Prepared,
138	    chain: RuntimeChain,
139	    account: LocalAccount,
140	    state: SenderState,
141	    log: Logger,
142	    gapNonce?: number,
143	  ): Promise<JobResult> {
144	    const { store } = this.#deps
145	    const nonce = gapNonce ?? state.pool.take()
146	    let sent: Awaited<ReturnType<typeof sendAttempt>>
147	    try {
148	      sent = await sendAttempt(store, chain, account, tx, { nonce, ...prepared }, this.#broadcast)
149	    } catch (error) {
150	      state.pool.rollback(nonce) // signing or saving failed: nothing was sent
151	      throw error
152	    }
153	    const { attempt, result } = sent
154	
155	    if (result.outcome !== 'rejected') {
156	      store.setAttemptOutcome(attempt.id, result.outcome)
157	      store.markSubmitted(tx.id, attempt.hash)
158	      log.info({ nonce, hash: attempt.hash, outcome: result.outcome }, 'submitted')
159	      return 'submitted'
160	    }
161	
162	    // Every send was answered with a rejection, so no node has the transaction: give the nonce
163	    // back, then drop any nonce the chain has already used (ADR 0009).
164	    store.setAttemptOutcome(attempt.id, 'rejected')
165	    state.pool.rollback(nonce)
166	    await this.#resync(state, chain, tx.sender, log)
167	    const code = result.reason === 'insufficient_funds' ? 'INSUFFICIENT_FUNDS' : 'BROADCAST_REJECTED'
168	    return this.#fail(tx, { code, message: result.message }, log)
169	  }
170	
171	  /** Drops available nonces the chain has already used, so an out-of-sync pool heals itself. */
172	  async #resync(state: SenderState, chain: RuntimeChain, sender: Address, log: Logger): Promise<void> {
173	    try {
174	      state.pool.reset(await chain.rpc.read.getTransactionCount({ address: sender, blockTag: 'latest' }))
175	    } catch (error) {
176	      log.warn({ err: error }, 'could not read the nonce to resync the pool')
177	    }
178	  }
179	
180	  #fail(tx: TxRecord, failure: Failure, log: Logger): JobResult {
181	    this.#deps.store.markFailed(tx.id, failure.code, failure.message)
182	    log.warn(failure, 'failed')
183	    return 'final'
184	  }
185	
186	  #chain(chainId: number): RuntimeChain {
187	    const chain = this.#deps.chains.get(chainId)
188	    if (!chain) throw new Error(`chain ${chainId} is not enabled`)
189	    return chain
190	  }
191	}
192	
193	/** Gas limit and fees. viem already retries each read (ADR 0008), so a failure here ends the request. */
194	async function prepare(tx: TxRecord, chain: RuntimeChain): Promise<Prepared | Failure> {
195	  const { gas } = chain.config
196	  try {
197	    const gasLimit = await estimateGasLimit(chain.rpc.read, tx, gas.gasLimitBufferPercent)
198	    const fees = priceFees(await readMarketFees(chain.rpc.read, gas.type), gas)
199	    if (fees === 'above_cap') {
200	      return { code: 'FEE_ABOVE_CAP', message: `base fee plus tip is above the cap of ${gas.maxFeePerGasWei} wei` }
201	    }
202	    return { gasLimit, fees }
203	  } catch (error) {
204	    const answer = describeSendError(error)
205	    if (answer.answered) {
206	      const funds = classifyNodeMessage(answer.message) === 'insufficient_funds'
207	      return { code: funds ? 'INSUFFICIENT_FUNDS' : 'ESTIMATION_REVERTED', message: answer.message }
208	    }
209	    if (isTransportError(error)) return { code: 'RPC_UNAVAILABLE', message: 'the RPC could not be reached' }
210	    throw error
211	  }
212	}
