import { setTimeout as sleep } from 'node:timers/promises'
import { afterEach, beforeEach, expect, test } from 'vitest'
import { buildHealth } from '../../src/executor/health'
import { startAnvil, unreachableUrl, type AnvilNode } from '../helpers/anvil'
import { ADDRESS_0, ADDRESS_1 } from '../helpers/keys'
import { ANVIL, createRuntime, type TestRuntime } from '../helpers/runtime'

let node: AnvilNode

beforeEach(async () => {
  node = await startAnvil()
})

afterEach(() => node.stop())

function report(rt: TestRuntime) {
  return buildHealth({ store: rt.store, chains: new Map([[ANVIL, rt.chain]]), senders: rt.senders, signers: rt.signers })
}

test("reports each chain's RPC and each sender's nonces, slots and queue", async () => {
  const rt = await createRuntime(node.url, { chain: { maxInFlightPerSender: 1 } })
  await rt.testClient.setAutomine(false) // keep the first request in flight
  rt.submit()
  rt.submit()
  await rt.worker.idle()

  expect(await report(rt)).toEqual({
    status: 'ok',
    chains: [
      {
        chainId: ANVIL,
        rpc: { reachable: true, latestBlock: '0' },
        senders: [
          { address: ADDRESS_0, nextNonce: 1, gaps: [], blockedByGap: false, inFlight: 1, queued: 1, stuck: 0 },
          { address: ADDRESS_1, nextNonce: 0, gaps: [], blockedByGap: false, inFlight: 0, queued: 0, stuck: 0 },
        ],
      },
    ],
  })
})

test('counts a submitted request as stuck once stuckAfterMs has passed since it was last replaced', async () => {
  const rt = await createRuntime(node.url, { chain: { stuckAfterMs: 100 } })
  await rt.testClient.setAutomine(false)
  rt.submit()
  await rt.worker.idle()
  await sleep(150)

  const { chains } = await report(rt)
  expect(chains[0].senders[0]).toMatchObject({ address: ADDRESS_0, stuck: 1 })
})

test('shows a gap that has outlived stuckAfterMs, which the gap filler could not fill', async () => {
  const rt = await createRuntime(node.url, { chain: { stuckAfterMs: 100 } })
  const pool = rt.senders.get(ANVIL, ADDRESS_0).pool
  const gap = pool.take()
  pool.take()
  pool.rollback(gap)
  await sleep(150)

  const { chains } = await report(rt)
  expect(chains[0].senders[0]).toMatchObject({ gaps: [0], blockedByGap: true, nextNonce: 2 })
})

test('is degraded when a chain RPC cannot be reached', async () => {
  const rt = await createRuntime(await unreachableUrl(), { initialNonce: 0 })
  expect(await report(rt)).toMatchObject({ status: 'degraded', chains: [{ rpc: { reachable: false } }] })
})

