import { createHash } from 'node:crypto'
import express, { type Express, type NextFunction, type Request, type Response } from 'express'
import { type Address, getAddress, type Hex, isAddress } from 'viem'
import { z } from 'zod'
import type { Signers } from './config/signers'
import type { HealthReport } from './executor/health'
import type { Logger } from './logger'
import type { Attempt, Store } from './store/store'
import {
  chainId,
  type ChainId,
  describeFailure,
  type Fees,
  type QueuedTx,
  type Receipt,
  type Transaction,
  type TxFailure,
  txId,
} from './types'

export type AppDeps = {
  store: Store
  chainIds: ReadonlySet<ChainId>
  signers: Signers
  /** Hands a newly stored request to the worker. */
  onAccepted: (tx: QueuedTx) => void
  health: () => Promise<HealthReport>
  logger: Logger
}

type ErrorCode =
  | 'VALIDATION_ERROR'
  | 'IDEMPOTENCY_KEY_MISSING'
  | 'IDEMPOTENCY_KEY_REUSED'
  | 'UNSUPPORTED_CHAIN'
  | 'UNKNOWN_SENDER'
  | 'NOT_FOUND'
  | 'PAYLOAD_TOO_LARGE'
  | 'INTERNAL_ERROR'

const BODY_LIMIT = '256kb'
const IDEMPOTENCY_KEY = /^[\x20-\x7e]{1,255}$/ // printable ASCII (ADR 0010)
const DECIMAL = /^(0|[1-9]\d*)$/
const UINT256_LIMIT = 2n ** 256n

const address = z.string().refine((value) => isAddress(value, { strict: false }), 'must be a 20-byte hex address')

const TransactionRequest = z.strictObject({
  chainId: z.number().int().positive(),
  sender: address,
  to: address,
  value: z
    .string()
    .regex(DECIMAL, 'must be an amount of wei as a decimal string')
    .refine((value) => !DECIMAL.test(value) || BigInt(value) < UINT256_LIMIT, 'must fit in 256 bits'),
  data: z.string().regex(/^0x([0-9a-fA-F]{2})*$/, 'must be 0x-prefixed hex bytes').default('0x'),
})

export function buildApp(deps: AppDeps): Express {
  const { store } = deps
  const app = express()
  app.disable('x-powered-by')
  app.use(express.json({ limit: BODY_LIMIT }))

  app.post('/transactions', (req, res) => {
    const key = req.get('Idempotency-Key')
    if (!key) {
      return sendError(res, 400, 'IDEMPOTENCY_KEY_MISSING', 'the Idempotency-Key header is required')
    }
    if (!IDEMPOTENCY_KEY.test(key)) {
      return sendError(res, 400, 'VALIDATION_ERROR', 'Idempotency-Key must be 1 to 255 printable ASCII characters')
    }

    const parsed = TransactionRequest.safeParse(req.body)
    if (!parsed.success) {
      const issues = parsed.error.issues.map((issue) => ({ path: issue.path.join('.'), message: issue.message }))
      return sendError(res, 400, 'VALIDATION_ERROR', 'the request body is invalid', { issues })
    }

    const chain = chainId(parsed.data.chainId)
    if (!deps.chainIds.has(chain)) {
      const supported = [...deps.chainIds]
      return sendError(res, 400, 'UNSUPPORTED_CHAIN', `chain ${chain} is not configured`, { supported })
    }
    const sender = getAddress(parsed.data.sender)
    if (!deps.signers.has(sender)) {
      return sendError(res, 400, 'UNKNOWN_SENDER', `no key is configured for ${sender}`)
    }

    const request = {
      chainId: chain,
      sender,
      to: getAddress(parsed.data.to),
      value: BigInt(parsed.data.value),
