import type { Address } from 'viem'
import type { Signers } from '../config/signers'
import type { Store } from '../store/store'
import type { ChainId, Nonce } from '../types'
import type { RuntimeChain } from './rpc'
import type { SenderRegistry } from './senders'

export type SenderHealth = {
  address: Address
  /** The next nonce never used. */
  nextNonce: Nonce
  /** Nonces given back and not reused yet. The lowest one blocks every nonce above it. */
  gaps: Nonce[]
  /** A gap has been open for stuckAfterMs, so the gap filler couldn't fill it: usually an unfunded sender. */
  blockedByGap: boolean
  /** Requests holding one of the sender's slots (ADR 0012). */
  inFlight: number
  /** Requests waiting for a slot. */
  queued: number
  /** Submitted requests not mined within stuckAfterMs of their last replacement. */
  stuck: number
}

export type ChainHealth = {
  chainId: ChainId
  rpc: { reachable: true; latestBlock: string } | { reachable: false }
  senders: SenderHealth[]
}

/** Degraded when any chain's RPC can't be reached. */
export type HealthReport = { status: 'ok' | 'degraded'; chains: ChainHealth[] }

export type HealthDeps = {
  store: Store
  chains: Map<ChainId, RuntimeChain>
  senders: SenderRegistry
  signers: Signers
}

export async function buildHealth({ store, chains, senders, signers }: HealthDeps): Promise<HealthReport> {
  const report = await Promise.all(
    [...chains].map(async ([id, chain]): Promise<ChainHealth> => {
      const { stuckAfterMs } = chain.config
      const submitted = store.listByStatus(['submitted'], id)
      return {
        chainId: id,
        rpc: await rpcHealth(chain),
        senders: [...signers.keys()].map((address) => {
          const state = senders.get(id, address)
          return {
            address,
            nextNonce: state.pool.top,
            gaps: state.pool.gaps,
            blockedByGap: state.pool.hasGap(stuckAfterMs),
            inFlight: state.active.size,
            queued: state.queue.length,
            stuck: submitted.filter((tx) => tx.sender === address && Date.now() - Date.parse(tx.updatedAt) > stuckAfterMs)
              .length,
          }
        }),
      }
    }),
  )
  const reachable = report.every((chain) => chain.rpc.reachable)
  return { status: reachable ? 'ok' : 'degraded', chains: report }
}

async function rpcHealth(chain: RuntimeChain): Promise<ChainHealth['rpc']> {
  try {
    return { reachable: true, latestBlock: (await chain.rpc.read.getBlockNumber()).toString() }
  } catch {
    return { reachable: false }
  }
}

