import { z } from 'zod'
import type { Signers } from './config/signers'
import type { Logger } from './logger'
import type { Attempt, AttemptOutcome, Store } from './store/store'
import {
  chainId,
  type ChainId,
  describeFailure,
  type Fees,
  type FailureCode,
  type Nonce,
  type QueuedTx,
  type Receipt,
  type Transaction,
  type TxFailure,
  txId,
  type TxId,
  type TxKind,
  type TxStatus,
} from './types'

export type AppDeps = {
  store: Store
  chainIds: ReadonlySet<ChainId>
  signers: Signers
  /** Hands a newly stored request to the worker. */
  onAccepted: (tx: QueuedTx) => void
  logger: Logger
