  id: TxId
  kind: TxKind
  status: TxStatus
  chainId: ChainId
  sender: Address
  to: Address
  value: string
  data: Hex
  nonce: Nonce | null
  gasLimit: string | null
  hash: Hash | null
  attempts: { hash: Hash; outcome: AttemptOutcome; fees: ApiFees; createdAt: string }[]
  receipt: ApiReceipt | null
  failure: ApiFailure | null
  createdAt: string
  updatedAt: string
}

