  { type: 'eip1559'; maxFeePerGas: string; maxPriorityFeePerGas: string } | { type: 'legacy'; gasPrice: string }

type ApiReceipt = {
  transactionHash: Hash
  blockNumber: string
  blockHash: Hash
  gasUsed: string
  effectiveGasPrice: string
  status: Receipt['status']
