      return send(res, HTTP.BAD_REQUEST, ApiResponse.error('VALIDATION_ERROR', message))
    }

    const parsed = TransactionRequest.safeParse(req.body)
    if (!parsed.success) {
      const issues = parsed.error.issues.map((issue) => ({ path: issue.path.join('.'), message: issue.message }))
      return send(res, HTTP.BAD_REQUEST, ApiResponse.error('VALIDATION_ERROR', 'the request body is invalid', { issues }))
    }

