    if (inserted.created) {
      deps.onAccepted(inserted.tx)
      return send(res, HTTP.ACCEPTED, ApiResponse.ok(toApiTransaction(inserted.tx, [])))
    }
    if (inserted.tx.requestHash !== requestHash) {
