      return send(res, HTTP.UNPROCESSABLE_ENTITY, ApiResponse.error('IDEMPOTENCY_KEY_REUSED', message))
    }
    res.set('Idempotent-Replayed', 'true')
    send(res, HTTP.OK, ApiResponse.ok(toApiTransaction(inserted.tx, store.attempts(inserted.tx.id))))
  })

  app.get('/transactions/:id', (req, res) => {
    const tx = store.get(txId(req.params.id))
