    send(res, HTTP.OK, ApiResponse.ok(toApiTransaction(tx, store.attempts(tx.id))))
  })

  // Liveness only, as plain text: not part of the JSON API.
  app.get('/health', (_req, res) => {
    res.type('text/plain').send('Online')
  })

  app.use((_req, res) => send(res, HTTP.NOT_FOUND, ApiResponse.error('NOT_FOUND', 'no such route')))

  // Express recognises an error handler by its four parameters.
  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    const type = (error as { type?: unknown } | null)?.type
    if (type === 'entity.parse.failed') {
      return send(res, HTTP.BAD_REQUEST, ApiResponse.error('VALIDATION_ERROR', 'the body is not valid JSON'))
    }
    if (type === 'entity.too.large') {
      return send(res, HTTP.PAYLOAD_TOO_LARGE, ApiResponse.error('PAYLOAD_TOO_LARGE', `the body is over ${BODY_LIMIT}`))
    }
    deps.logger.error({ err: error }, 'unhandled error')
    send(res, HTTP.INTERNAL_SERVER_ERROR, ApiResponse.error('INTERNAL_ERROR', 'internal error'))
  })

  return app
}

/** A fingerprint of the normalised request, to tell a replay from a key reused for something else (ADR 0010). */
function hashRequest(request: { chainId: ChainId; sender: Address; to: Address; value: bigint; data: Hex }): string {
