// End-to-end run: real anvil node + real service (src/main.ts), driven over HTTP only.
import { spawn } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { mkdirSync, openSync, readFileSync, rmSync } from 'node:fs'
import { setTimeout as sleep } from 'node:timers/promises'
import { createPublicClient, createTestClient, createWalletClient, http, parseEther, parseGwei } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { anvil } from 'viem/chains'

const PROJECT = '/Users/sainathr19/Desktop/evm-transaction-executor'
const DIR = new URL('./e2e-run/', import.meta.url).pathname
const RPC = 'http://127.0.0.1:18560'
const API = 'http://127.0.0.1:3930'
// anvil's public dev keys
const KEY_0 = '0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80'
const KEY_1 = '0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d'
const S0 = '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266'
const S1 = '0x70997970C51812dc3A010C7d01b50e0d17dc79C8'
const TO = '0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC'
const STUCK_WAIT_MS = 6_500 // anvil config: stuckAfterMs 5000, pollIntervalMs 500

const pub = createPublicClient({ chain: anvil, transport: http(RPC) })
const node = createTestClient({ chain: anvil, mode: 'anvil', transport: http(RPC) })
const outsider = (key) => createWalletClient({ account: privateKeyToAccount(key), chain: anvil, transport: http(RPC) })

let anvilProc
let service
const results = []

function check(name, ok, detail = '') {
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `\n      ${detail}` : ''}`)
}

async function waitUntil(condition, timeoutMs, what) {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    if (await condition().catch(() => false)) return
    await sleep(100)
  }
  throw new Error(`timed out waiting for ${what}`)
}

async function startService() {
  const log = openSync(`${DIR}/service.log`, 'a')
  service = spawn('node', ['--import', 'tsx', 'src/main.ts'], {
    cwd: PROJECT,
    env: {
      PATH: process.env.PATH,
      RPC_URL_31337: RPC,
      SIGNER_PRIVATE_KEYS: `${KEY_0},${KEY_1}`,
      PORT: '3930',
      DB_PATH: `${DIR}/executor.db`,
      LOG_LEVEL: 'info',
    },
    stdio: ['ignore', log, log],
  })
  await waitUntil(async () => (await fetch(`${API}/health`)).ok, 15_000, 'the service to start')
}

async function stopService() {
  const exited = new Promise((resolve) => service.once('exit', resolve))
  service.kill('SIGTERM')
  await exited
}

const transfer = (overrides = {}) => ({ chainId: 31337, sender: S0, to: TO, value: '1000000000000000', ...overrides })

async function post(body, key = randomUUID()) {
  const headers = { 'content-type': 'application/json' }
  if (key !== null) headers['idempotency-key'] = key
  const res = await fetch(`${API}/transactions`, { method: 'POST', headers, body: JSON.stringify(body) })
  return { status: res.status, replayed: res.headers.get('idempotent-replayed'), body: await res.json() }
}

async function get(id) {
  return (await (await fetch(`${API}/transactions/${id}`)).json()).result
}

async function until(id, statuses, timeoutMs = 20_000) {
  let tx
  await waitUntil(async () => statuses.includes((tx = await get(id)).status), timeoutMs, `${id} to be ${statuses}`)
  return tx
}

async function scenario(name, run) {
  try {
    await run()
  } catch (error) {
    check(name, false, error.message)
  } finally {
    await node.setAutomine(true).catch(() => {})
  }
}

// ---------------------------------------------------------------------------------------------------

rmSync(DIR, { recursive: true, force: true })
mkdirSync(DIR, { recursive: true })
anvilProc = spawn('anvil', ['--port', '18560', '--silent'], { stdio: 'ignore' })
await waitUntil(async () => (await pub.getChainId()) === 31337, 10_000, 'anvil')
await startService()
console.log(`anvil ${RPC}, service ${API}\n`)

await scenario('health', async () => {
  const res = await fetch(`${API}/health`)
  check('GET /health answers Online', res.status === 200 && (await res.text()) === 'Online')
})

await scenario('happy path', async () => {
  const r = await post(transfer())
  const tx = await until(r.body.result.id, ['succeeded', 'failed', 'reverted'])
  check(
    'submit → 202 queued → succeeded with a receipt',
    r.status === 202 && r.body.status === 'ok' && r.body.result.status === 'queued' && tx.status === 'succeeded',
    `nonce ${tx.nonce}, gasLimit ${tx.gasLimit}, gasUsed ${tx.receipt?.gasUsed}, block ${tx.receipt?.blockNumber}`,
  )
})

await scenario('idempotency', async () => {
  const key = randomUUID()
  const first = await post(transfer({ value: '1' }), key)
  const replay = await post(transfer({ value: '1', sender: S0.toLowerCase() }), key)
  const reused = await post(transfer({ value: '2' }), key)
  check(
    'same key + same body → 200 replay of the same transaction',
    replay.status === 200 && replay.replayed === 'true' && replay.body.result.id === first.body.result.id,
  )
  check('same key + different body → 422 IDEMPOTENCY_KEY_REUSED', reused.status === 422 && reused.body.error?.code === 'IDEMPOTENCY_KEY_REUSED')
  await until(first.body.result.id, ['succeeded'])
})

await scenario('validation', async () => {
  const cases = [
    ['missing Idempotency-Key', await post(transfer(), null), 400, 'IDEMPOTENCY_KEY_MISSING'],
    ['bad address', await post(transfer({ to: '0x1234' })), 400, 'VALIDATION_ERROR'],
    ['value above uint256', await post(transfer({ value: (2n ** 256n).toString() })), 400, 'VALIDATION_ERROR'],
    ['unsupported chain', await post(transfer({ chainId: 1 })), 400, 'UNSUPPORTED_CHAIN'],
    ['sender with no key', await post(transfer({ sender: TO })), 400, 'UNKNOWN_SENDER'],
  ]
  for (const [name, res, status, code] of cases) {
    const envelope = res.body.status === 'error' && res.body.result === null
    check(`rejects ${name} → ${status} ${code}`, res.status === status && res.body.error?.code === code && envelope)
  }
})

await scenario('concurrency', async () => {
  const start = await pub.getTransactionCount({ address: S0 })
  const posted = await Promise.all(Array.from({ length: 20 }, (_, i) => post(transfer({ value: String(i + 1) }))))
  const txs = await Promise.all(posted.map((p) => until(p.body.result.id, ['succeeded', 'failed'], 30_000)))
  const nonces = txs.map((tx) => tx.nonce).sort((a, b) => a - b)
  const expected = Array.from({ length: 20 }, (_, i) => start + i)
  check(
    '20 concurrent requests from one sender (cap 16) → 20 distinct nonces, all mined',
    txs.every((tx) => tx.status === 'succeeded') && nonces.join() === expected.join(),
    `nonces ${nonces[0]}..${nonces.at(-1)}`,
  )
})

await scenario('two senders', async () => {
  const posted = await Promise.all(
    [S0, S1, S0, S1, S0, S1].map((sender, i) => post(transfer({ sender, value: String(100 + i) }))),
  )
  const txs = await Promise.all(posted.map((p) => until(p.body.result.id, ['succeeded', 'failed'])))
  const bySender = (s) => txs.filter((tx) => tx.sender === s).map((tx) => tx.nonce)
  const distinct = (list) => new Set(list).size === list.length
  check(
    'two senders in parallel → each gets its own nonce sequence',
    txs.every((tx) => tx.status === 'succeeded') && distinct(bySender(S0)) && distinct(bySender(S1)),
    `S0 nonces ${bySender(S0).join(',')}, S1 nonces ${bySender(S1).join(',')}`,
  )
})

await scenario('revert at estimation', async () => {
  const reverter = '0x000000000000000000000000000000000000dEaD'
  await node.setCode({ address: reverter, bytecode: '0x60006000fd' }) // REVERT(0, 0)
  const before = await pub.getTransactionCount({ address: S0 })
  const r = await post(transfer({ to: reverter }))
  const tx = await until(r.body.result.id, ['failed', 'succeeded'])
  const next = await until((await post(transfer())).body.result.id, ['succeeded'])
  check(
    'a call that would revert → failed ESTIMATION_REVERTED, no nonce used',
    tx.failure?.code === 'ESTIMATION_REVERTED' && tx.nonce === null && next.nonce === before,
    `failure: ${tx.failure?.message}`,
  )
})

await scenario('revert on chain', async () => {
  const target = '0x000000000000000000000000000000000000bEEF'
  await node.setAutomine(false)
  const r = await post(transfer({ to: target }))
  await until(r.body.result.id, ['submitted'])
  await node.setCode({ address: target, bytecode: '0x60006000fd' }) // reverts only once mined
  await node.mine({ blocks: 1 })
  const tx = await until(r.body.result.id, ['reverted', 'succeeded', 'failed'])
  check('mined but reverted → reverted, with the receipt', tx.status === 'reverted' && tx.receipt?.status === 'reverted')
})

await scenario('fee spike', async () => {
  await node.setNextBlockBaseFeePerGas({ baseFeePerGas: parseGwei('200') })
  await node.mine({ blocks: 1 })
  const tx = await until((await post(transfer())).body.result.id, ['failed', 'succeeded'])
  await node.setNextBlockBaseFeePerGas({ baseFeePerGas: parseGwei('1') })
  await node.mine({ blocks: 1 })
  check(
    'base fee above the 100 gwei cap → failed FEE_ABOVE_CAP',
    tx.failure?.code === 'FEE_ABOVE_CAP' && tx.failure?.capWei === parseGwei('100').toString(),
    `failure: ${tx.failure?.message}`,
  )
})

await scenario('insufficient funds', async () => {
  const balance = await pub.getBalance({ address: S1 })
  await node.setBalance({ address: S1, value: 0n })
  const tx = await until((await post(transfer({ sender: S1 }))).body.result.id, ['failed', 'succeeded'])
  await node.setBalance({ address: S1, value: balance })
  check('empty sender → failed INSUFFICIENT_FUNDS', tx.failure?.code === 'INSUFFICIENT_FUNDS', `failure: ${tx.failure?.message}`)
})

await scenario('stuck → fee bump', async () => {
  await node.setAutomine(false)
  const r = await post(transfer())
  const submitted = await until(r.body.result.id, ['submitted'])
  await sleep(STUCK_WAIT_MS)
  const bumped = await get(r.body.result.id)
  await node.mine({ blocks: 1 })
  const tx = await until(r.body.result.id, ['succeeded', 'failed'])
  const [first, second] = bumped.attempts
  check(
    'stuck past stuckAfterMs → replaced at the same nonce with higher fees, and the replacement is mined',
    bumped.attempts.length >= 2 &&
      BigInt(second.fees.maxFeePerGas) > BigInt(first.fees.maxFeePerGas) &&
      tx.status === 'succeeded' &&
      tx.nonce === submitted.nonce &&
      tx.hash === bumped.attempts.at(-1).hash,
    `maxFeePerGas ${first.fees.maxFeePerGas} → ${second?.fees.maxFeePerGas}, attempts ${bumped.attempts.length}`,
  )
})

await scenario('dropped from the mempool', async () => {
  await node.setAutomine(false)
  const r = await post(transfer())
  const submitted = await until(r.body.result.id, ['submitted'])
  await node.dropTransaction({ hash: submitted.hash })
  await sleep(STUCK_WAIT_MS)
  await node.mine({ blocks: 1 })
  const tx = await until(r.body.result.id, ['succeeded', 'failed'])
  check(
    'dropped by the node → sent again by the monitor, then mined',
    tx.status === 'succeeded' && tx.nonce === submitted.nonce,
    `attempts ${tx.attempts.length}`,
  )
})

await scenario('nonce used outside the service', async () => {
  const outside = await outsider(KEY_1).sendTransaction({ to: TO, value: 1n }) // takes S1's next nonce
  await pub.waitForTransactionReceipt({ hash: outside })
  const collided = await until((await post(transfer({ sender: S1 }))).body.result.id, ['failed', 'succeeded'])
  const next = await until((await post(transfer({ sender: S1 }))).body.result.id, ['succeeded', 'failed'])
  const count = await pub.getTransactionCount({ address: S1 })
  check(
    'outside tx took the nonce → request fails with nonce too low, pool resyncs, next request succeeds',
    collided.failure?.code === 'BROADCAST_REJECTED' && next.status === 'succeeded' && next.nonce === count - 1,
    `failure: ${collided.failure?.message}; next nonce ${next.nonce}`,
  )
})

await scenario('NONCE_TAKEN', async () => {
  await node.setAutomine(false)
  const r = await post(transfer())
  const submitted = await until(r.body.result.id, ['submitted'])
  // An outside tx replaces ours in the mempool at the same nonce and is mined.
  await outsider(KEY_0).sendTransaction({
    to: TO,
    value: 2n,
    nonce: submitted.nonce,
    maxFeePerGas: parseGwei('50'),
    maxPriorityFeePerGas: parseGwei('10'),
  })
  await node.mine({ blocks: 1 })
  const tx = await until(r.body.result.id, ['failed', 'succeeded'])
  check('outside tx replaced ours and was mined → failed NONCE_TAKEN', tx.failure?.code === 'NONCE_TAKEN', `failure: ${tx.failure?.message}`)
})

await scenario('restart', async () => {
  await node.setAutomine(false)
  const r = await post(transfer())
  const submitted = await until(r.body.result.id, ['submitted'])
  await stopService()
  await node.mine({ blocks: 1 }) // mined while the service is down
  await startService()
  const tx = await until(r.body.result.id, ['succeeded', 'failed'])
  await node.setAutomine(true)
  const after = await until((await post(transfer())).body.result.id, ['succeeded', 'failed'])
  check(
    'restart with a tx in flight → recovered, receipt found, and the next nonce follows on',
    tx.status === 'succeeded' && after.status === 'succeeded' && after.nonce === submitted.nonce + 1,
    `in-flight nonce ${submitted.nonce}, next nonce ${after.nonce}`,
  )
})

// ---------------------------------------------------------------------------------------------------

await stopService()
anvilProc.kill()

const lines = readFileSync(`${DIR}/service.log`, 'utf8').trim().split('\n')
const entries = lines.flatMap((line) => {
  try {
    return [JSON.parse(line)]
  } catch {
    return []
  }
})
const errors = entries.filter((entry) => entry.level >= 50)
const counts = {}
for (const entry of entries) counts[entry.msg] = (counts[entry.msg] ?? 0) + 1
console.log(`\nservice log: ${entries.length} lines, ${errors.length} at error level`)
for (const [msg, n] of Object.entries(counts).sort((a, b) => b[1] - a[1])) console.log(`  ${String(n).padStart(4)}  ${msg}`)
for (const entry of errors) console.log(`  ERROR ${entry.msg} ${JSON.stringify(entry.err?.message ?? '')}`)

const passed = results.filter(Boolean).length
console.log(`\n${passed}/${results.length} checks passed`)
process.exit(passed === results.length && errors.length === 0 ? 0 : 1)

