// Stress test: 1000 transfers through the real service, first clean, then with RPC faults injected by
// a proxy between the service and anvil. Test-only: nothing here is part of the service.
import { spawn } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { createServer } from 'node:http'
import { mkdirSync, openSync, readFileSync, rmSync } from 'node:fs'
import { setTimeout as sleep } from 'node:timers/promises'
import { createPublicClient, http } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { anvil } from 'viem/chains'

const PROJECT = '/Users/sainathr19/Desktop/evm-transaction-executor'
const DIR = new URL('./stress-run/', import.meta.url).pathname
const ANVIL = 'http://127.0.0.1:18570'
const PROXY_PORT = 18571
const API = 'http://127.0.0.1:3940'
const TRANSFERS = Number(process.env.TRANSFERS ?? 1000)
const KEYS = [
  '0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80',
  '0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d',
  '0x5de4111afa1a4b94908f83103eb1f1706367c2e68ca870fc3fb9a804cdab365a',
  '0x7c852118294e51e653712a81e05800f419141751be58f605c371e15141b007a6',
  '0x47e179ec197488593b187f80a00eb0da91f1b9d0b13f8733639f19c30a34926a',
]
const SENDERS = KEYS.map((key) => privateKeyToAccount(key).address)
const FINAL = new Set(['succeeded', 'reverted', 'failed'])

const chain = createPublicClient({ chain: anvil, transport: http(ANVIL) })
const results = []
const check = (name, ok, detail = '') => {
  results.push(ok)
  console.log(`  ${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`)
}

// --- Fault-injecting JSON-RPC proxy -----------------------------------------------------------------

const chaos = { reject: 0, lostReply: 0, blackhole: 0 }
const faults = { sends: 0, rejected: 0, lostReply: 0, blackholed: 0 }
const fate = new Map() // signed tx → 'blackhole' | 'normal', decided the first time it's seen

const forward = async (body) =>
  (await fetch(ANVIL, { method: 'POST', headers: { 'content-type': 'application/json' }, body })).text()

const proxy = createServer((req, res) => {
  let body = ''
  req.on('data', (chunk) => (body += chunk))
  req.on('end', async () => {
    const payload = JSON.parse(body)
    if (!Array.isArray(payload) && payload.method === 'eth_sendRawTransaction') {
      faults.sends++
      const raw = payload.params[0]
      if (!fate.has(raw)) fate.set(raw, Math.random() < chaos.blackhole ? 'blackhole' : 'normal')
      if (fate.get(raw) === 'blackhole') {
        faults.blackholed++
        return res.writeHead(502).end() // never reaches a node, every time it's sent
      }
      const roll = Math.random()
      if (roll < chaos.reject) {
        faults.rejected++
        res.writeHead(200, { 'content-type': 'application/json' })
        return res.end(JSON.stringify({ jsonrpc: '2.0', id: payload.id, error: { code: -32003, message: 'intrinsic gas too low' } }))
      }
      if (roll < chaos.reject + chaos.lostReply) {
        faults.lostReply++
        await forward(body) // the node takes it, but the reply is lost
        return res.writeHead(502).end()
      }
    }
    res.writeHead(200, { 'content-type': 'application/json' })
    res.end(await forward(body))
  })
})

// --- HTTP client with a cap on concurrent requests ---------------------------------------------------

let active = 0
const queue = []
async function limited(fn) {
  if (active >= 64) await new Promise((resolve) => queue.push(resolve))
  active++
  try {
    return await fn()
  } finally {
    active--
    queue.shift()?.()
  }
}

const post = (body) =>
  limited(async () => {
    const res = await fetch(`${API}/transactions`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'idempotency-key': randomUUID() },
      body: JSON.stringify(body),
    })
    return { status: res.status, body: await res.json() }
  })

const get = (id) => limited(async () => (await (await fetch(`${API}/transactions/${id}`)).json()).result)

// One poller for everything still in flight, instead of one polling loop per request.
const waiters = new Map()
let polling = true
const waitFinal = (id) => new Promise((resolve) => waiters.set(id, resolve))
async function poller() {
  while (polling) {
    await Promise.all(
      [...waiters.keys()].map(async (id) => {
        const tx = await get(id)
        if (FINAL.has(tx.status)) {
          waiters.get(id)?.(tx)
          waiters.delete(id)
        }
      }),
    )
    await sleep(250)
  }
}

// --- One phase ---------------------------------------------------------------------------------------

async function runPhase(name, recipient, faultRates) {
  Object.assign(chaos, faultRates)
  const faultsBefore = { ...faults }
  const startNonces = await Promise.all(SENDERS.map((address) => chain.getTransactionCount({ address })))
  const startBalance = await chain.getBalance({ address: recipient })
  const transfers = Array.from({ length: TRANSFERS }, (_, i) => ({ sender: SENDERS[i % SENDERS.length], value: BigInt(i + 1) }))
  const rejections = []
  const t0 = Date.now()

  // A client that resubmits, with a new key, when the node rejected its request (ADR 0009).
  const deliver = async (transfer) => {
    for (let tries = 1; tries <= 10; tries++) {
      const r = await post({ chainId: 31337, sender: transfer.sender, to: recipient, value: transfer.value.toString() })
      if (r.status !== 202) throw new Error(`POST answered ${r.status}: ${JSON.stringify(r.body.error)}`)
      const tx = await waitFinal(r.body.result.id)
      if (tx.status === 'succeeded') return tx
      if (tx.failure?.code !== 'BROADCAST_REJECTED') throw new Error(`unexpected ${tx.status}: ${tx.failure?.message}`)
      rejections.push(tx)
    }
    throw new Error('rejected 10 times')
  }

  const settled = await Promise.allSettled(transfers.map(deliver))
  const elapsed = (Date.now() - t0) / 1000
  const delivered = settled.filter((s) => s.status === 'fulfilled').map((s) => s.value)
  const errors = settled.filter((s) => s.status === 'rejected').map((s) => s.reason.message)

  console.log(`\n${name}: ${TRANSFERS} transfers from ${SENDERS.length} senders`)
  check('every transfer ends as succeeded', errors.length === 0, errors.length ? `${errors.length} errors, first: ${errors[0]}` : '')

  const expected = transfers.reduce((sum, t) => sum + t.value, 0n)
  const received = (await chain.getBalance({ address: recipient })) - startBalance
  check('exactly once: recipient received exactly the sum of all transfers', received === expected, `${received} of ${expected} wei`)

  let noncesOk = true
  let countsOk = true
  for (const [i, sender] of SENDERS.entries()) {
    const nonces = delivered.filter((tx) => tx.sender === sender).map((tx) => tx.nonce).sort((a, b) => a - b)
    const contiguous = nonces.every((n, j) => n === startNonces[i] + j)
    const used = (await chain.getTransactionCount({ address: sender })) - startNonces[i]
    noncesOk &&= contiguous
    countsOk &&= used === nonces.length
  }
  check('each sender: nonces contiguous from its start, none reused', noncesOk)
  check("each sender: on-chain nonce count rose by exactly its succeeded requests", countsOk)
  check(
    'every succeeded request is recorded under the hash that was mined',
    delivered.every((tx) => tx.receipt?.transactionHash === tx.hash && tx.receipt.status === 'success'),
  )

  const latencies = delivered.map((tx) => Date.parse(tx.updatedAt) - Date.parse(tx.createdAt)).sort((a, b) => a - b)
  const pct = (p) => latencies[Math.min(latencies.length - 1, Math.floor((p / 100) * latencies.length))]
  const attempts = {}
  for (const tx of delivered) attempts[tx.attempts.length] = (attempts[tx.attempts.length] ?? 0) + 1
  const injected = Object.fromEntries(Object.keys(faults).map((k) => [k, faults[k] - faultsBefore[k]]))
  console.log(`  time ${elapsed.toFixed(1)} s, ${(TRANSFERS / elapsed).toFixed(0)} transfers/s`)
  console.log(`  accepted → mined: p50 ${pct(50)} ms, p95 ${pct(95)} ms, max ${latencies.at(-1)} ms`)
  console.log(`  attempts per mined request: ${JSON.stringify(attempts)}; requests rejected and resubmitted: ${rejections.length}`)
  console.log(`  proxy: ${JSON.stringify(injected)}`)
}

// --- Run ---------------------------------------------------------------------------------------------

rmSync(DIR, { recursive: true, force: true })
mkdirSync(DIR, { recursive: true })
const anvilProc = spawn('anvil', ['--port', '18570', '--silent'], { stdio: 'ignore' })
for (let i = 0; i < 100; i++) {
  if (await chain.getChainId().catch(() => null)) break
  await sleep(100)
}
await new Promise((resolve) => proxy.listen(PROXY_PORT, '127.0.0.1', resolve))

const log = openSync(`${DIR}/service.log`, 'a')
const service = spawn('node', ['--import', 'tsx', 'src/main.ts'], {
  cwd: PROJECT,
  env: {
    PATH: process.env.PATH,
    RPC_URL_31337: `http://127.0.0.1:${PROXY_PORT}`,
    SIGNER_PRIVATE_KEYS: KEYS.join(','),
    PORT: '3940',
    DB_PATH: `${DIR}/executor.db`,
    LOG_LEVEL: 'info',
  },
  stdio: ['ignore', log, log],
})
for (let i = 0; i < 150; i++) {
  if ((await fetch(`${API}/health`).catch(() => null))?.ok) break
  await sleep(100)
}
void poller()

await runPhase('Phase 1, clean', '0x000000000000000000000000000000000000c1ea', { reject: 0, lostReply: 0, blackhole: 0 })
await runPhase('Phase 2, faults injected', '0x000000000000000000000000000000000000c2ea', {
  reject: 0.05,
  lostReply: 0.05,
  blackhole: 0.02,
})

polling = false
service.kill('SIGTERM')
await new Promise((resolve) => service.once('exit', resolve))
proxy.close()
anvilProc.kill()

const entries = readFileSync(`${DIR}/service.log`, 'utf8')
  .trim()
  .split('\n')
  .flatMap((line) => {
    try {
      return [JSON.parse(line)]
    } catch {
      return []
    }
  })
const errorEntries = entries.filter((entry) => entry.level >= 50)
console.log(`\nservice log: ${entries.length} lines`)
check('no errors in the service log', errorEntries.length === 0, errorEntries[0]?.msg ?? '')

const passed = results.filter(Boolean).length
console.log(`\n${passed}/${results.length} checks passed`)
process.exit(passed === results.length ? 0 : 1)

