import { createPublicClient, fallback, http, type Hash, type Hex, type PublicClient } from 'viem'
import { sendRawTransaction } from 'viem/actions'
import { ConfigError } from '../config/error'
import type { EnabledChain } from '../config/load'
import { type ChainId, chainId as toChainId } from '../types'

/** Sends a signed transaction to one RPC URL, exactly once. */
export type Sender = (raw: Hex) => Promise<Hash>

export type ChainRpc = {
  chainId: ChainId
  /** For reads: viem's retries with backoff, then the next URL (ADR 0008, layer 1). */
  read: PublicClient
  /**
   * For broadcasts: one per URL, in fallback order. Not viem's fallback transport: it moves to the
   * next URL without saying an earlier send went unanswered, so broadcast() does its own
   * (ADR 0008, layer 3). viem's sendRawTransaction already skips retries; turning them off on the
   * transport keeps that true for any other send path.
   */
  senders: Sender[]
}

/** An enabled chain with its RPC clients. */
export type RuntimeChain = { config: EnabledChain; rpc: ChainRpc }

export function createChainRpc(chain: EnabledChain): ChainRpc {
  const transports = chain.rpcUrls.map((url) => http(url))
  const read = createPublicClient({
    chain: chain.chain,
    transport: transports.length === 1 ? transports[0] : fallback(transports),
  })
  const senders = chain.rpcUrls.map((url): Sender => {
    const client = createPublicClient({ chain: chain.chain, transport: http(url, { retryCount: 0 }) })
    return (raw) => sendRawTransaction(client, { serializedTransaction: raw })
  })
  return { chainId: toChainId(chain.chain.id), read, senders }
}

/**
 * Startup check (ADR 0005): every RPC URL of a chain must serve that chain. Each URL is checked,
 * so a wrong fallback URL can't hide behind a correct first one. Messages never include the URL.
 */
export async function verifyChainId(chain: EnabledChain): Promise<void> {
  const expected = chain.chain.id
  await Promise.all(
    chain.rpcUrls.map(async (url, i) => {
      const where = `RPC_URL_${expected} entry ${i + 1}`
      let actual: number
      try {
        actual = await createPublicClient({ transport: http(url, { retryCount: 1 }) }).getChainId()
      } catch {
        throw new ConfigError(`${where} could not be reached to check its chain id`)
      }
      if (actual !== expected) throw new ConfigError(`${where} serves chain ${actual}, not ${expected}`)
    }),
  )
}
}

export async function readMarketFees(client: PublicClient, type: GasConfig['type']): Promise<MarketFees> {
  if (type === 'legacy') return { type: 'legacy', gasPrice: await client.getGasPrice() }

  const [block, tip] = await Promise.all([
    client.getBlock({ blockTag: 'latest' }),
    client.estimateMaxPriorityFeePerGas(),
  ])
  if (block.baseFeePerGas === null) {
    throw new Error(`chain ${client.chain?.id} has no base fee: set gas.type to 'legacy' in its config file`)
  }
  return { type: 'eip1559', baseFee: block.baseFeePerGas, tip }
}

export async function estimateGasLimit(client: PublicClient, tx: GasRequest, bufferPercent: number): Promise<bigint> {
  const estimate = await client.estimateGas({ account: tx.sender, to: tx.to, value: tx.value, data: tx.data })
  return applyGasBuffer(estimate, bufferPercent)
}

/** A percentage in basis points: 12.5 → 1250. */
function bps(percent: number): bigint {
  return BigInt(Math.round(percent * 100))
}

function mulDivUp(value: bigint, numerator: bigint, denominator: bigint): bigint {
  return (value * numerator + denominator - 1n) / denominator
}

function max(a: bigint, b: bigint): bigint {
  return a > b ? a : b
}

function min(a: bigint, b: bigint): bigint {
  return a < b ? a : b
}

14:The worker computes gas and fees just before signing, never when the POST arrives, because fee estimates go stale within seconds. We call viem's estimation functions directly rather than `prepareTransactionRequest`, so the buffer, multiplier and cap live in our code, in one place.
42:### Fees: legacy
44:Chains without EIP-1559 set `type: 'legacy'` in their config and use `eth_gasPrice`. The type is set in config rather than detected, which removes one way for things to fail.
46:### Fee cap
50:- If `baseFee + tip`, or the legacy `gasPrice`, is already above the cap, the transaction couldn't be mined right now. The request becomes `failed` with `FEE_ABOVE_CAP`. It isn't kept waiting for fees to drop; the client decides whether to retry.
51:- Otherwise `maxFeePerGas` is clamped to the cap, as shown above.
52:- Fee bumps ([ADR 0008](0008-retries-and-failure-handling.md)) are capped the same way.
73:- **Waiting in the queue while fees are above the cap.** Rejected for now, because it hides latency from the client.
79:- Two dependent transactions sent back to back (approve, then swap) can fail estimation, because the first isn't mined yet. One sender's requests also aren't guaranteed to be mined in order ([ADR 0012](0012-in-flight-cap.md)), so a client should wait for the first to finish before sending the second.

